const readStoredJson=(key,fallback)=>{try{const value=localStorage.getItem(key);return value?JSON.parse(value):fallback}catch(error){console.warn(`Ignoring invalid saved ${key} value:`,error.message);try{localStorage.removeItem(key)}catch{};return fallback}};
