async function loadCurrentProfile(){if(!currentUser)return {data:null};let result=await supabase.from('profiles').select('*').eq('id',currentUser.id).maybeSingle();if(!result?.data&&currentUser.email)result=await supabase.from('profiles').select('*').eq('email',currentUser.email).maybeSingle();return result}
const customerStatusLabel=status=>{const value=typeof status==='string'?status:'pending';return ({pending:'Order received',confirmed:'Confirmed',preparing:'Being prepared',ready_for_delivery:'Ready for delivery',out_for_delivery:'Out for delivery',delivered:'Delivered',cancelled:'Not delivered'})[value]||'Order received'};
const orderTrackingMarkup=status=>{const steps=[['pending','Received'],['confirmed','Confirmed'],['preparing','Preparing'],['out_for_delivery','On the way'],['delivered','Delivered']],current=steps.findIndex(step=>step[0]===status);return `<div class="summary-tracking"><div class="summary-tracking-head"><strong>Live order tracking</strong><span>${escapeHtml(customerStatusLabel(status))}</span></div><div class="tracking-steps">${steps.map((step,index)=>`<span class="${status==='cancelled'?'':index<=current?'is-done':''} ${step[0]===status?'is-current':''}"><i>${index<=current&&status!=='cancelled'?'✓':'·'}</i>${step[1]}</span>`).join('')}</div></div>`};
const riderPhotoMarkup=rider=>rider?.profile_photo_url?`<img class="rider-photo" src="${escapeHtml(rider.profile_photo_url)}" alt="${escapeHtml(rider.full_name||'Rider')}" loading="lazy">`:'<span class="rider-photo rider-photo-fallback">🚴</span>';
const orderRiderMarkup=order=>order.rider_id?`<div class="assigned-rider" data-rider-id="${escapeHtml(order.rider_id)}">${riderPhotoMarkup({profile_photo_url:order.rider_photo_url,full_name:order.rider_name})}<span class="rider-name">${escapeHtml(order.rider_name||'Rider assigned')}</span>${order.rider_phone?`<span class="rider-actions"><a href="tel:${escapeHtml(order.rider_phone)}" aria-label="Call rider" title="Call rider">📞</a><a href="sms:${escapeHtml(order.rider_phone)}" aria-label="Message rider" title="Message rider">💬</a></span>`:''}</div>`:'<div class="assigned-rider muted">A rider will appear here once assigned.</div>';
const orderSummaryRiderMarkup=rider=>rider?.full_name||rider?.phone||rider?.profile_photo_url?`<div class="summary-rider">${riderPhotoMarkup(rider)}<span>Delivered by <strong>${escapeHtml(rider.full_name||'Rider')}</strong><small>${Number(rider.total_deliveries||0)} deliveries · ${Number(rider.average_rating||0).toFixed(1)} ★</small></span><button class="text-button" type="button" onclick="showRiderAccount('${escapeHtml(rider.id||'')}')">View account</button>${rider.phone?`<a href="tel:${escapeHtml(rider.phone)}" aria-label="Call rider" title="Call rider">📞</a>`:''}</div>`:'';
async function showRiderAccount(riderId){if(!riderId)return;const [profileResult,ordersResult,reviewsResult]=await Promise.all([supabase.from('profiles').select('id,full_name,phone,profile_photo_url,vehicle_type,delivery_area').eq('id',riderId).maybeSingle(),supabase.from('orders').select('id').eq('rider_id',riderId).eq('status','delivered'),supabase.from('rider_reviews').select('rating,communication,carefulness,punctuality').eq('rider_id',riderId)]);const rider=profileResult?.data||{},reviews=reviewsResult?.data||[],deliveries=ordersResult?.data?.length||0;const avg=key=>reviews.length?(reviews.reduce((sum,row)=>sum+Number(row[key]||0),0)/reviews.length).toFixed(1):'—';document.querySelector('#rider-account-modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="auth-modal" id="rider-account-modal" onclick="if(event.target.id==='rider-account-modal')this.remove()"><div class="auth-card rider-account-card"><button class="close" onclick="this.closest('#rider-account-modal').remove()">×</button><div class="rider-account-hero">${riderPhotoMarkup(rider)}<div><div class="eyebrow">Rider account</div><h2>${escapeHtml(rider.full_name||'Delivery partner')}</h2><p>${escapeHtml(rider.vehicle_type||'Verified delivery partner')}${rider.delivery_area?` · ${escapeHtml(rider.delivery_area)}`:''}</p></div></div><div class="rider-stat-grid"><div><strong>${deliveries}</strong><small>Total deliveries</small></div><div><strong>${avg('rating')} ★</strong><small>Customer rating</small></div><div><strong>${reviews.length}</strong><small>Reviews</small></div></div><div class="rider-criteria"><h3>Customer ratings</h3><div><span>Communication</span><strong>${avg('communication')} / 5</strong></div><div><span>Carefulness</span><strong>${avg('carefulness')} / 5</strong></div><div><span>Punctuality</span><strong>${avg('punctuality')} / 5</strong></div></div><div class="rider-tip-box"><h3>Leave a tip</h3><div class="tip-options">${[20,50,100].map(value=>`<button type="button">₹${value}</button>`).join('')}<button type="button">No tip</button></div><small>Tips can be added after delivery confirmation.</small></div><button class="checkout" onclick="this.closest('#rider-account-modal').remove()">Done</button></div></div>`)}
async function hydrateRiderDetails(){for(const node of document.querySelectorAll('.assigned-rider[data-rider-id]:not([data-rider-loaded])')){node.dataset.riderLoaded='true';const result=await supabase.from('profiles').select('full_name,phone,profile_photo_url').eq('id',node.dataset.riderId).maybeSingle();if(result?.data){node.outerHTML=orderRiderMarkup({rider_id:node.dataset.riderId,rider_name:result.data.full_name,rider_phone:result.data.phone,rider_photo_url:result.data.profile_photo_url})}}}
