function productImageMarkup(product){const image=product?.image_url?.trim();return image?`<img src="${escapeHtml(image)}" alt="${escapeHtml(product.name||'Product')}" loading="lazy" onerror="this.hidden=true;this.nextElementSibling.hidden=false"/><span hidden>${product.emoji||'🛍️'}</span>`:(product?.emoji||'🛍️')}
function categoryOf(product){const value=`${product.category_name||product.category?.name||product.name}`.toLowerCase();if(value.includes('hotel essential'))return'hotel_essentials';if(value.includes('restaurant')||value.includes('supply'))return'restaurant_supplies';return value.includes('fruit')||/apple|banana|pear|plum|mango|orange/.test(value)?'fruits':value.includes('vegetable')||/potato|tomato|onion|pea|corn/.test(value)?'vegetables':'other'}
function selectCategory(category){activeCategory=category;render();document.querySelector('#products')?.scrollIntoView({behavior:'smooth'})}
