function cartStorageKey(){return currentUser?`pahalgam-cart-${currentUser.id}`:"pahalgam-cart"}function save(){localStorage.setItem("pahalgam-cart",JSON.stringify(cart));if(currentUser)localStorage.setItem(cartStorageKey(),JSON.stringify(cart));if(currentUser)void syncCloudCart()}
let cloudCartSyncing=false;
async function syncCloudCart(){if(!currentUser||cloudCartSyncing)return;cloudCartSyncing=true;try{let result=await supabase.from('carts').select('id').eq('user_id',currentUser.id).maybeSingle();let cartId=result?.data?.id;if(!cartId){const created=await supabase.from('carts').insert({user_id:currentUser.id}).maybeSingle();cartId=created?.data?.id}if(!cartId)return;await supabase.from('cart_items').delete().eq('cart_id',cartId);if(cart.length)await supabase.from('cart_items').insert(cart.map(item=>({cart_id:cartId,product_id:item.id,quantity:item.qty})));}catch(error){console.warn('Cloud cart sync unavailable:',error.message)}finally{cloudCartSyncing=false}}
async function hydrateCloudCart(){if(!currentUser)return;try{const saved=localStorage.getItem(cartStorageKey());if(saved){cart=JSON.parse(saved).filter(item=>Number(item.qty)>0);render()}const cartResult=await supabase.from("carts").select("id").eq("user_id",currentUser.id).maybeSingle();const cartId=cartResult?.data?.id;if(!cartId){if(cart.length)await syncCloudCart();return}const itemsResult=await supabase.from("cart_items").select("product_id,quantity").eq("cart_id",cartId);const cloudItems=Array.isArray(itemsResult?.data)?itemsResult.data:[];if(cloudItems.length){cart=cloudItems.filter(item=>Number(item.quantity)>0).map(item=>({id:item.product_id,qty:Number(item.quantity)}));localStorage.setItem("pahalgam-cart",JSON.stringify(cart));localStorage.setItem(cartStorageKey(),JSON.stringify(cart));render()}else if(cart.length)await syncCloudCart()}catch(error){console.warn("Cloud cart load unavailable:",error.message)}}
let cloudCartHydratedFor='';setInterval(()=>{if(currentUser&&cloudCartHydratedFor!==currentUser.id){cloudCartHydratedFor=currentUser.id;void hydrateCloudCart()}},1000);
function saveBrowseState(state){localStorage.setItem('pahalgam-browse-state',JSON.stringify(state));if(state?.category){const slug=encodeURIComponent(state.category);history.replaceState(null,'',`#category-hub-${slug}`)}}
function restoreBrowseState(){try{const saved=JSON.parse(localStorage.getItem('pahalgam-browse-state')||'null');const hashCategory=location.hash.startsWith('#category-hub-')?decodeURIComponent(location.hash.slice('#category-hub-'.length)):null;const state=saved?.category?saved:(hashCategory?{category:hashCategory}:null);if(!state?.category)return;showCategoryPage(state.category);if(state.subcategory)setTimeout(()=>window.showSubcategoryProducts?.(state.subcategory),900)}catch(error){console.warn('Browse state restore failed:',error.message)}}
function cartQty(id){return cart.find(item=>String(item.id)===String(id))?.qty||0}
function header(){const saved=readStoredJson('pahalgam-last-delivery',null);return `<header class="header"><div class="header-inner"><div class="logo"><span class="logo-mark">⌁</span>GroVale</div><div class="search"><span class="search-icon">⌕</span><input id="search" autocomplete="off" placeholder="Search food, essentials, vendors…" /><div class="search-suggestions" id="search-suggestions" role="listbox" hidden></div></div><div class="delivery-target" id="delivery-target"><span>📍</span><span><small>Delivering to</small><strong>${escapeHtml(compactDeliveryLabel(saved?.label||saved?.address||'Pahalgam'))}</strong></span><button type="button" onclick="changeDeliveryTarget()">View</button></div><div class="header-actions"><div class="account-menu"><button type="button" class="pill-btn" id="account">Account</button><div class="account-dropdown" id="account-dropdown"><button onclick="accountMenuAction('profile')">Profile</button><button onclick="accountMenuAction('addresses')">My addresses</button><button onclick="accountMenuAction('orders')">My orders</button><button onclick="accountMenuAction('prescriptions')">My prescriptions</button><button class="logout-option" onclick="accountMenuAction('logout')">Logout</button></div></div><button type="button" class="pill-btn primary" id="cart">Cart <span class="badge">${cart.reduce((a,i)=>a+i.qty,0)}</span></button></div></div></header>`}
function changeDeliveryTarget(){if(currentUser){accountMenuAction('addresses')}else{showAuthModal()}}
function toggleDeliveryAddress(){document.querySelector('#delivery-target')?.classList.toggle('expanded')}
function setupDeliveryTarget(){const target=document.querySelector('#delivery-target');if(!target||target.dataset.ready)return;target.dataset.ready='true';const button=target.querySelector('button');if(button){button.textContent='';button.setAttribute('aria-label','Expand delivery address');button.onclick=event=>{event.preventDefault();event.stopPropagation();toggleDeliveryAddress()}}const saved=readStoredJson('pahalgam-last-delivery',null);const savedLabel=escapeHtml(compactDeliveryLabel(saved?.label||saved?.address||'Choose a saved address'));target.insertAdjacentHTML('beforeend',`<button type="button" class="delivery-change">View</button><div class="delivery-dropdown" role="menu"><div class="delivery-dropdown-head"><div class="delivery-dropdown-title">Deliver to</div><button type="button" class="delivery-dropdown-close" data-delivery-action="close" aria-label="Close delivery options">×</button></div><div class="delivery-search"><input type="search" placeholder="Search or enter location" aria-label="Search delivery location"/><button type="button" data-delivery-action="search">Use</button></div><button type="button" data-delivery-action="current"><span class="delivery-option-icon">⌖</span><span>Use current location</span></button><button type="button" data-delivery-action="add"><span class="delivery-option-icon">＋</span><span>Add new address</span></button><button type="button" class="delivery-saved-option" data-delivery-action="saved"><span class="delivery-option-icon">⌂</span><span>${savedLabel}</span></button></div>`);const changeButton=target.querySelector('.delivery-change');changeButton.onclick=event=>{event.preventDefault();event.stopPropagation();toggleDeliveryAddress()};target.querySelectorAll('[data-delivery-action]').forEach(item=>item.onclick=event=>{event.preventDefault();event.stopPropagation();const action=item.dataset.deliveryAction;if(action==='close'){target.classList.remove('expanded');return}if(action==='search')applyDeliverySearch(target);if(action==='current'){target.classList.remove('expanded');showDeliveryMapPicker(target)}if(action==='add')addNewAddress(event);if(action==='saved'){target.classList.remove('expanded');if(currentUser)accountMenuAction('addresses');else showAuthModal()}})}
function showDeliveryMapPicker(target){document.querySelector('#delivery-map-picker')?.remove();document.body.insertAdjacentHTML('beforeend','<div class="delivery-map-overlay" id="delivery-map-picker"><div class="delivery-map-card"><div class="delivery-dropdown-head"><div><div class="delivery-dropdown-title">Choose location</div><h3>Set your delivery point</h3></div><button type="button" class="delivery-dropdown-close" onclick="this.closest(\'#delivery-map-picker\').remove()">×</button></div><div class="delivery-map-surface" id="delivery-map-surface"><span class="delivery-map-pin">📍</span><strong>Finding your location…</strong><small>Allow location access, then confirm the pin</small></div><button type="button" class="delivery-map-locate" onclick="locateDeliveryMap()">Locate me</button><button type="button" class="checkout" onclick="confirmDeliveryMapLocation()">Use this location</button></div></div>');locateDeliveryMap()}
function locateDeliveryMap(){const map=document.querySelector('#delivery-map-picker'),surface=document.querySelector('#delivery-map-surface');if(!map||!surface)return;if(!navigator.geolocation){surface.querySelector('strong').textContent='Location unavailable';surface.querySelector('small').textContent='Enter your address manually instead';return}surface.querySelector('strong').textContent='Requesting location…';navigator.geolocation.getCurrentPosition(position=>{map.dataset.location=`${position.coords.latitude},${position.coords.longitude}`;surface.querySelector('strong').textContent='Current location found';surface.querySelector('small').textContent=`${position.coords.latitude.toFixed(5)}, ${position.coords.longitude.toFixed(5)}`},()=>{surface.querySelector('strong').textContent='Location access is off';surface.querySelector('small').textContent='Enable location permission or enter an address manually'})}
function confirmDeliveryMapLocation(){const map=document.querySelector('#delivery-map-picker'),target=document.querySelector('#delivery-target');const value=map?.dataset.location||'Pahalgam';localStorage.setItem('pahalgam-last-delivery',JSON.stringify({address:value,label:value==='Pahalgam'?'Pahalgam':'Selected location'}));if(target?.querySelector('strong'))target.querySelector('strong').textContent=value==='Pahalgam'?'Pahalgam':'Selected location';map?.remove()}
function applyDeliverySearch(target){const input=target?.querySelector('.delivery-search input'),value=input?.value.trim();if(!value)return;localStorage.setItem('pahalgam-last-delivery',JSON.stringify({address:value,label:value}));const label=target.querySelector('strong');if(label)label.textContent=value;target.classList.remove('expanded')}
function useCurrentDeliveryLocation(target){if(!navigator.geolocation){target.classList.remove('expanded');return}navigator.geolocation.getCurrentPosition(position=>{const value=`Current location (${position.coords.latitude.toFixed(4)}, ${position.coords.longitude.toFixed(4)})`;localStorage.setItem('pahalgam-last-delivery',JSON.stringify({address:value,label:'Current location'}));const label=target.querySelector('strong');if(label)label.textContent='Current location';target.classList.remove('expanded')},()=>target.classList.remove('expanded'),{enableHighAccuracy:true,timeout:10000})}
document.addEventListener('click',event=>{const target=event.target.closest('#delivery-target');if(target&&!event.target.closest('button,.delivery-dropdown'))toggleDeliveryAddress()});
async function hydrateDeliveryTarget(){const target=document.querySelector('#delivery-target');if(!target||!currentUser)return;try{const result=await supabase.from('addresses').select('*').eq('user_id',currentUser.id).order('created_at',{ascending:false}).maybeSingle();const address=result?.data;if(!address)return;const phone=address.phone||currentUser.phone||'';const full=[address.address_line||address.address,address.hotel_name,address.room_number?`Room ${address.room_number}`:'',phone?`Phone ${phone}`:'',address.delivery_instructions].filter(Boolean).join(' · ')||'Pahalgam';const value=normalizeDeliveryLabel(full);const street=String(address.address_line||address.address||'').split(',')[0].trim();const label=normalizeDeliveryLabel(`${address.label||'Home'} · ${street}`);localStorage.setItem('pahalgam-last-delivery',JSON.stringify({address:value,label}));target.querySelector('strong').textContent=label;const savedButton=target.querySelector('.delivery-saved-option');if(savedButton){const text=savedButton.querySelector('span:last-child');if(text)text.textContent=label}}catch(error){console.warn('Delivery target unavailable:',error.message)}}
function showInfoPage(label){const pages={Blog:['Local delivery notes from Pahalgam','Updates about local vendors, seasonal products, and delivery tips will appear here.'],Privacy:['Privacy policy','We use your account and delivery details only to process orders, provide support, and improve the service. We do not sell personal information.'],Terms:['Terms of service','Orders are confirmed subject to product availability and service-area coverage. Cash-on-delivery orders are payable when delivered.'],FAQs:['Frequently asked questions','Delivery is available across Pahalgam. ASAP delivery is usually 15–30 minutes when the service area and stock permit. Contact support for order changes.'],Security:['Security','Authentication is handled through Supabase. Never share sign-in links or one-time passwords with anyone.'],Contact:['Contact support','For order help, email hello@grovale.in and include your order number.'],Partner:['Partner with us','Local restaurants, hotels, shops, and suppliers can contact support to discuss onboarding.'],Franchise:['Franchise enquiries','For expansion or franchise enquiries, contact hello@grovale.in.'],Seller:['Sell on Pahalgam Delivery','Approved sellers can manage products, stock, and orders through the merchant workspace.'],Warehouse:['Warehouse enquiries','For warehouse and fulfilment partnerships, contact hello@grovale.in.'],Deliver:['Become a delivery partner','Riders help collect orders from merchants and deliver them across Pahalgam. Contact support to apply.'],Resources:['Resources','Merchant and rider workspaces provide the tools needed to manage orders and deliveries.']};const page=pages[label]||pages.Contact;document.querySelector('#info-modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="info-modal" id="info-modal" role="dialog" aria-modal="true"><div class="info-card"><button class="close" aria-label="Close" onclick="document.querySelector('#info-modal')?.remove()">×</button><div class="eyebrow">Pahalgam Delivery</div><h2>${escapeHtml(page[0])}</h2><p>${escapeHtml(page[1])}</p><button class="checkout" onclick="document.querySelector('#info-modal')?.remove()">Continue browsing</button></div></div>`)}
function footer(){const categoryLink=name=>`<a href="#category-hub" onclick="event.preventDefault();showCategoryPage('${name.replace(/'/g,"\\'")}');document.querySelector('#category-hub')?.scrollIntoView({behavior:'smooth'})">${name}</a>`;return `<footer class="site-footer"><div class="footer-column"><div class="eyebrow">Useful links</div><nav class="footer-links" aria-label="Useful links">${footerLinks.map(label=>`<a href="#${label.toLowerCase()}" onclick="event.preventDefault();showInfoPage('${label}')">${label}</a>`).join('')}</nav></div><div class="footer-column footer-categories"><div class="footer-heading"><div><div class="eyebrow">Categories</div></div><button type="button" class="see-all" aria-expanded="false" onclick="toggleFooterCategories(this)">See all</button></div><nav class="footer-category-grid" aria-label="Categories">${footerCategories.map((name,index)=>`<span class="footer-category-item ${index>=12?'footer-category-extra':''}" ${index>=12?'hidden':''}>${categoryLink(name)}</span>`).join('')}</nav></div></footer>`}
function contextualBanners(){return `<section class="contextual-banners" aria-label="Featured delivery banners"><div class="contextual-heading"><div class="banner-controls"><button type="button" aria-label="Previous banner" onclick="moveContextBanners(-1)">←</button><button type="button" aria-label="Next banner" onclick="moveContextBanners(1)">→</button></div></div><div class="banner-track" id="banner-track">${contextBanners.map((banner,index)=>`<article class="context-banner ${banner.tone}" data-banner-index="${index}" style="background-image:linear-gradient(90deg,rgba(13,35,28,.88) 0%,rgba(13,35,28,.5) 42%,rgba(13,35,28,.08) 100%),url('${banner.image}')"><div class="banner-copy"><div class="eyebrow">${banner.eyebrow}</div><h3>${banner.title}</h3><p>${banner.copy}</p><button type="button" class="banner-action" onclick="showToastMessage('${banner.action} coming soon')">${banner.action}</button></div></article>`).join('')}</div></section>`}
function moveContextBanners(direction){const track=document.querySelector('#banner-track');if(!track)return;track.scrollBy({left:direction*(track.clientWidth*.86),behavior:'smooth'})}
function startContextBannerAutoScroll(){clearInterval(contextualBannerTimer);contextualBannerTimer=setInterval(()=>moveContextBanners(1),3000)}
function toggleFooterCategories(button){const expanded=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!expanded));button.textContent=expanded?'See all':'Show fewer';document.querySelectorAll('.footer-category-extra').forEach(item=>item.hidden=expanded)}
function home(){const storeLabels={individual:'GroVale Fresh',hotel_guest:'Valley Guest Store',hotel_essentials:'Stay Essentials',restaurant_supplies:'Pahalgam Provisions'},storeImages={individual:'public/banners/fresh-arrivals.png',hotel_guest:'public/banners/popular.png',hotel_essentials:'public/banners/hotel-essentials.png',restaurant_supplies:'public/banners/restaurants.png'};return `${header()}<main class="main"><section id="category-browser"></section><section><div class="section-head"><h2>Shop by store</h2><span>Choose a store to get started</span></div><div class="category-grid shop-by-store-grid">${Object.entries(types).map(([key,t])=>`<button class="category store-category" onclick="chooseType('${key}')"><div class="category-icon store-category-image" style="background-image:url('${storeImages[key]}')"><span>${t.icon}</span></div><strong>${storeLabels[key]}</strong><small>${t.label} orders</small></button>`).join('')}</div></section>${contextualBanners()}</main>${footer()}<div class="toast" id="toast">Added to cart</div><div class="drawer" id="drawer"><div class="drawer-panel" id="drawer-panel"></div></div>`}
function render(){const existingHub=document.querySelector('#category-hub');const preserveHub=existingHub&&!existingHub.querySelector('.category-page-head');app.innerHTML=home();applyGroValeBrand();if(preserveHub){const target=document.querySelector('#category-browser, #products');target?.before(existingHub)}else renderCategoryHub();bind();}
function addHomeTrustStrip(){const main=document.querySelector('.main');if(!main||document.querySelector('.home-trust-strip'))return;main.insertAdjacentHTML('afterbegin',`<section class="home-trust-strip" aria-label="Delivery information"><div><strong>📍 Serving Pahalgam</strong><span>Hotel, home and business delivery</span></div><div><strong>⚡ 15–30 min delivery</strong><span>For ASAP orders in the service area</span></div><div><strong>💵 Cash on delivery</strong><span>Pay when your order arrives</span></div></section>`)}
function addTrustFooter(){if(document.querySelector('.trust-footer'))return;document.querySelector('.main')?.insertAdjacentHTML('beforeend',`<footer class="trust-footer"><div><strong>Delivery coverage</strong><span>We deliver across Pahalgam to homes, hotels, guest houses, and local businesses.</span></div><div><strong>Cancellation & refunds</strong><span>Contact us before preparation begins to request cancellation. If an item is unavailable or incorrect, contact support for help.</span></div><div><strong>Customer support</strong><span><a href="mailto:hello@grovale.in">hello@grovale.in</a><br/>We’re happy to help with orders and delivery questions.</span></div></footer>`)}
function addCategoryTrustDetails(){document.querySelector('.category-trust')?.remove();document.querySelector('.trust-footer')?.remove()}
function addProductUnits(){document.querySelectorAll('.product').forEach(card=>{if(card.querySelector('.product-unit'))return;const product=products.find(item=>item.name===card.querySelector('h3')?.textContent);if(product?.unit)card.querySelector('.product-footer')?.insertAdjacentHTML('beforebegin',`<small class="product-unit">${escapeHtml(product.unit)}</small>`)})}
function addStickyCart(){if(document.querySelector('.sticky-cart'))return;document.body.insertAdjacentHTML('beforeend','<button type="button" class="sticky-cart" aria-label="Open cart">🛒 <span>Cart</span> <b></b></button>');const button=document.querySelector('.sticky-cart');button.onclick=cartEntryPoint;const update=()=>{const quantity=cart.reduce((sum,item)=>sum+item.qty,0);button.hidden=!quantity;button.style.display=quantity?'flex':'none';button.querySelector('b').textContent=quantity?`${quantity} items · ${money(cartTotals().grand)}`:''};update();window.setInterval(update,500)}
function addCustomerProductFilters(){const section=document.querySelector('#products');const grid=section?.querySelector('.product-grid');if(!section||!grid||section.querySelector('.customer-product-filters'))return;section.querySelector('.section-head')?.insertAdjacentHTML('afterend',`<div class="customer-product-filters" aria-label="Product filters"><label>Price <select id="customer-price-filter"><option value="all">Any price</option><option value="under-100">Under ₹100</option><option value="100-500">₹100–₹500</option><option value="over-500">Over ₹500</option></select></label><label>Availability <select id="customer-stock-filter"><option value="all">All products</option><option value="available">In stock only</option><option value="out">Out of stock</option></select></label></div>`);const apply=()=>{const price=document.querySelector('#customer-price-filter').value,stock=document.querySelector('#customer-stock-filter').value;grid.querySelectorAll('.product').forEach(card=>{const product=products.find(item=>item.name===card.querySelector('h3')?.textContent),value=Number(product?.price||0),available=product?.stock_quantity==null||Number(product.stock_quantity)>0;const priceMatch=price==='all'||price==='under-100'&&value<100||price==='100-500'&&value>=100&&value<=500||price==='over-500'&&value>500;const stockMatch=stock==='all'||stock==='available'&&available||stock==='out'&&!available;card.hidden=!(priceMatch&&stockMatch)})};document.querySelector('#customer-price-filter').onchange=apply;document.querySelector('#customer-stock-filter').onchange=apply}
function categoryImage(name){const value=name.toLowerCase();if(value==='vegetables & fruits')return'public/vegetables and fruits.jpg';if(value==='atta, rice & dal')return'public/atta rice and dal.jpg';if(value==='oil, ghee & masala')return'public/oil ghee and masala.jpg';if(value==='dairy, bread & eggs')return'public/dairy bread and eggs.jpg';if(value==='bakery & biscuits')return'public/bakery and biscuits.jpg';if(value==='dry fruits & cereals')return'public/dry fruits and cereals.jpg';if(value==='chicken, meat & fish')return'public/chicken meat and fish.jpg';if(value==='kitchenware & appliances')return'public/kitchenware and appliances.jpg';if(value==='chips & namkeen')return'public/chips and namkeen.jpg';if(value==='sweets & chocolates')return'public/sweets and chocolates.jpg';if(value==='drinks & juices')return'public/drinks and juices.jpg';if(value==='tea, coffee & milk drinks')return'public/tea coffee and milk drinks.jpg';if(value==='instant food')return'public/instant food.jpg';if(value==='sauces & spreads')return'public/sauces and spreads.jpg';if(value==='bath & body')return'public/bath and body.jpg';if(value==='hair')return'public/hair.jpg';if(value==='skin & face')return'public/skin and face.jpg';if(value==='beauty & cosmetics')return'public/beauty and cosmetics.jpg';if(value==='feminine hygiene')return'public/feminine hygiene.jpg';if(value==='baby care')return'public/baby care.jpg';if(value==='health & pharma')return'public/health and pharma.jpg';if(value==='sexual wellness')return'public/sexual wellness.jpg';if(value==='home & lifestyle')return'public/home and lifestyle.jpg';if(value==='cleaners & repellents')return'public/cleaners and repellents.jpg';if(value==='print store')return'public/print store.jpg';if(value==='e-gift cards')return'public/e-gift cards.jpg';if(value==='festival gifts')return'public/festival gifts.jpg';if(value==='electronics')return'public/electronics.jpg';if(value==='stationery & games')return'public/stationery and games.jpg';if(value==='frozen foods')return'public/frozen foods.jpg';if(value==='oral care')return'public/oral care.jpg';if(value==='men’s grooming')return'public/mens grooming.jpg';if(value==='fragrances')return'public/fragrances.jpg';if(value==='laundry')return'public/laundry.jpg';if(value==='mobile accessories')return'public/mobile accessories.jpg';if(value==='travel essentials')return'public/travel essentials.jpg';if(/fresh|vegetable|fruit|bakery|dairy|meat|trout/.test(value))return'public/banners/fresh-arrivals.png';if(/hotel|household|clean|stationery|baby|personal|home/.test(value))return'public/banners/hotel-essentials.png';if(/restaurant|kitchen|packaging/.test(value))return'public/banners/restaurants.png';if(/deal|gift|snack|beverage|popular/.test(value))return'public/banners/deals.png';return'public/banners/popular.png'}
function renderCategoryHub(){const target=document.querySelector('#category-browser, #products');if(!target)return;document.querySelector('#category-hub')?.remove();const card=name=>`<div class="compact-category-wrap"><button class="compact-category" onclick="showCategoryPage('${name.replace(/'/g,"\\'")}')"><img class="compact-category-image" src="${categoryImage(name)}" alt="" loading="lazy" decoding="async"><span>${categoryIcon(name)}</span><strong>${name}</strong></button><span class="compact-category-label">${name}</span></div>`;const groups=Object.entries(categoryGroups).map(([group,names])=>`<section class="category-group" aria-labelledby="category-group-${group.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}"><h3 id="category-group-${group.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}">${group}</h3><div class="compact-category-grid">${names.filter(name=>categoryCatalog[name]).map(card).join('')}</div></section>`).join('');const allCategories=`<div class="compact-category-grid">${Object.keys(categoryCatalog).map(card).join('')}</div>`;target.insertAdjacentHTML('beforebegin',`<section id="category-hub" class="category-hub"><div class="section-head"><div><div class="eyebrow">Browse the store</div><h2>Categories</h2></div></div><div class="category-groups-mobile">${groups}</div><div class="category-list-desktop">${allCategories}</div></section>`)}
function categoryIcon(name){if(/fruit|vegetable/i.test(name))return'🥦';if(/atta|rice|dal/i.test(name))return'🌾';if(/dairy|bread|egg|bakery/i.test(name))return'🥛';if(/bath|skin|hair|beauty|feminine|baby/i.test(name))return'🧴';if(/health|sexual/i.test(name))return'🩺';if(/chicken|meat|fish/i.test(name))return'🍗';if(/electronic/i.test(name))return'🔌';if(/stationery|game/i.test(name))return'🎲';if(/hotel/i.test(name))return'🏨';if(/restaurant|kitchen/i.test(name))return'🍽️';return'🛍️'}
function showCategoryPage(name){const hub=document.querySelector('#category-hub');if(!hub)return;saveBrowseState({category:name});hub.innerHTML=`<div class="category-page-head"><button class="text-button category-back" onclick="localStorage.removeItem('pahalgam-browse-state');renderCategoryHub()">← All categories</button><div class="eyebrow">${categoryIcon(name)} Category</div><h2>${name}</h2><p>Browse related ${name.toLowerCase()} products.</p></div><div class="subcategory-grid">${categoryCatalog[name].map(sub=>`<button class="subcategory-tile" onclick="showSubcategoryProducts('${sub.replace(/'/g,"\\'")}')"><strong>${sub}</strong><span>View products →</span></button>`).join('')}</div><div id="subcategory-products"></div>`}
function showSubcategoryProducts(subcategory){const target=document.querySelector('#subcategory-products');if(!target)return;const category=JSON.parse(localStorage.getItem('pahalgam-browse-state')||'{}').category;saveBrowseState({category:category||'Vegetables & Fruits',subcategory});const patterns={"Fresh vegetables":/potato|tomato|onion|pea|corn|vegetable/i,"Fresh fruits":/apple|banana|pear|plum|fruit|mango|orange/i,"Leafy greens":/spinach|lettuce|greens|cabbage/i,"Herbs":/herb|mint|coriander|parsley/i};const pattern=patterns[subcategory]||new RegExp(subcategory,'i');const matches=products.filter(product=>pattern.test(`${product.name} ${product.desc}`));target.innerHTML=`<div class="filtered-products-head"><div><div class="eyebrow">Vegetables & Fruits</div><h3>${subcategory}</h3><span>${matches.length} products</span></div><button class="text-button" onclick="localStorage.removeItem('pahalgam-browse-state');document.querySelector('#subcategory-products').innerHTML=''">Clear</button></div>${matches.length?`<div class="product-grid">${matches.map(product=>`<article class="product"><div class="product-image">${product.emoji}</div><h3>${product.name}</h3><p>${product.desc}</p><div class="product-footer"><span>${money(product.price)}</span><button class="add" onclick="add(${product.id})">Add +</button></div></article>`).join('')}</div>`:'<div class="empty">No products found in this subcategory yet.</div>'}`;target.scrollIntoView({behavior:'smooth',block:'start'})}
function bind(){document.querySelector('#cart').onclick=openCart;document.querySelector('#account').onclick=toggleAccountMenu;document.querySelector('#drawer').onclick=e=>{if(e.target.id==='drawer')closeDrawer()};document.querySelector('#search').oninput=e=>{const q=e.target.value.toLowerCase().trim();let visible=0;document.querySelectorAll('#products .product').forEach(x=>{const match=!q||x.innerText.toLowerCase().includes(q);x.style.display=match?'':'none';if(match)visible++});const count=document.querySelector('#product-result-count');if(count)count.textContent=q?`${visible} matching product${visible===1?'':'s'}`:'Choose a category to browse'};document.querySelectorAll('.add').forEach(button=>button.onclick=()=>add(button.dataset.productId));document.addEventListener('click',closeAccountMenuOnOutside,{once:true});addStickyCart();const hub=document.querySelector('#category-hub'),banners=document.querySelector('.contextual-banners');if(hub&&banners){const categoryGroups=hub.querySelector('.category-groups-mobile')||hub.querySelector('.category-list-desktop');if(categoryGroups)categoryGroups.before(banners);else hub.after(banners)}document.querySelectorAll('.home-trust-strip,.trust-footer').forEach(node=>node.remove());addCategoryTrustDetails();addCustomerProductFilters();addProductUnits();startContextBannerAutoScroll()}
function toggleAccountMenu(event){event?.stopPropagation();document.querySelector('#account-dropdown')?.classList.toggle('open')}
function closeAccountMenuOnOutside(event){const menu=document.querySelector('.account-menu');if(menu&&!menu.contains(event.target))menu.querySelector('.account-dropdown')?.classList.remove('open');setTimeout(()=>document.addEventListener('click',closeAccountMenuOnOutside,{once:true}),0)}
async function accountMenuAction(action){document.querySelector('#account-dropdown')?.classList.remove('open');if(action==='logout'){if(currentUser)signOut();else showAuthModal();return}if(!currentUser){showAuthModal();return}await accountPage();const target={profile:'account-profile',addresses:'account-addresses',orders:'account-orders',prescriptions:'account-prescriptions'}[action];const button=[...document.querySelectorAll('.account-sidebar button')].find(item=>item.textContent.toLowerCase().includes(action==='addresses'?'addresses':action==='orders'?'orders':action==='prescriptions'?'prescriptions':'profile'));if(target)showAccountSection(target,button)}
function showToastMessage(message){let toast=document.querySelector('#toast');if(!toast){toast=document.createElement('div');toast.id='toast';toast.className='toast';document.body.appendChild(toast)}toast.classList.remove('item-added-toast');toast.textContent=message;toast.style.display='block';toast.style.zIndex='1100';if(window.matchMedia('(max-width:600px)').matches){Object.assign(toast.style,{top:'auto',right:'12px',bottom:'max(12px, env(safe-area-inset-bottom))',left:'12px',width:'auto',maxWidth:'none',transform:'none',textAlign:'center'})}else{Object.assign(toast.style,{top:'50%',right:'auto',bottom:'auto',left:'50%',width:'auto',maxWidth:'calc(100vw - 32px)',transform:'translate(-50%, -50%)'})}clearTimeout(window.stockToastTimer);window.stockToastTimer=setTimeout(()=>toast.style.display='none',3200)}
function addNewAddress(event){event?.preventDefault();if(!currentUser){showAuthModal();return}document.querySelector('#address-modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="auth-modal" id="address-modal"><div class="auth-card"><button class="close" onclick="this.closest('#address-modal').remove()">×</button><div class="eyebrow">Saved delivery details</div><h2>Add new address</h2><label for="new-address-label">Address label</label><input id="new-address-label" placeholder="Home or Office" maxlength="40"/><label for="new-address-line">House or street address</label><input id="new-address-line" placeholder="House number, street, landmark" maxlength="160"/><label for="new-address-locality">Locality or area</label><input id="new-address-locality" placeholder="Colony, mohalla, village" maxlength="100"/><label for="new-address-district">District</label><input id="new-address-district" placeholder="District" maxlength="80"/><label for="new-address-city">City or town</label><input id="new-address-city" placeholder="City or town" maxlength="80"/><label for="new-address-state">State</label><input id="new-address-state" placeholder="State" maxlength="80" value="Jammu and Kashmir"/><label for="new-address-pincode">PIN code</label><input id="new-address-pincode" inputmode="numeric" placeholder="PIN code" maxlength="6"/><label for="new-address-phone">Phone number</label><input id="new-address-phone" type="tel" inputmode="tel" placeholder="Phone for delivery" maxlength="20" value="${escapeHtml(currentUser.phone||'')}"/><button class="checkout" onclick="saveNewAddress(this)">Save address</button><div id="address-message"></div></div></div>`)}
async function saveNewAddress(button){const label=document.querySelector('#new-address-label')?.value.trim()||'Home';const street=document.querySelector('#new-address-line')?.value.trim();const locality=document.querySelector('#new-address-locality')?.value.trim();const district=document.querySelector('#new-address-district')?.value.trim();const city=document.querySelector('#new-address-city')?.value.trim();const state=document.querySelector('#new-address-state')?.value.trim();const pincode=document.querySelector('#new-address-pincode')?.value.trim();const address_line=[street,locality,district,city,state,pincode?`PIN ${pincode}`:''].filter(Boolean).join(', ');const phone=document.querySelector('#new-address-phone')?.value.trim();const message=document.querySelector('#address-message');if(!street||!district||!city||!pincode){if(message)message.textContent='Enter the house or street, district, city or town, and PIN code.';return}if(!phone){if(message)message.textContent='Enter a phone number for delivery.';return}if(button){button.disabled=true;button.textContent='Saving…'}const result=await supabase.from('addresses').insert({user_id:currentUser.id,label,address_line,hotel_name:null,room_number:null,delivery_instructions:null});if(result?.error){if(message)message.textContent=result.error.message;if(button){button.disabled=false;button.textContent='Save address'}return}await supabase.from('profiles').update({phone,updated_at:new Date().toISOString()}).eq('id',currentUser.id);currentUser.phone=phone;const fullAddress=[address_line,`Phone ${phone}`].filter(Boolean).join(' · ');localStorage.setItem('pahalgam-last-delivery',JSON.stringify({address:fullAddress,label:`${label} · ${fullAddress}`}));document.querySelector('#address-modal')?.remove();await accountPage()}
const orderSummaryAddressObserver=new MutationObserver(async()=>{const modal=document.querySelector('#order-summary-modal');const bill=modal?.querySelector('.summary-bill');if(!modal||!bill)return;modal.querySelectorAll('.summary-address').forEach((row,index)=>{if(index>0)row.remove()});if(modal.querySelector('.summary-address')||modal.dataset.addressLoading==='true')return;const match=modal.querySelector('h2')?.textContent?.match(/#(.+)/);if(!match)return;modal.dataset.addressLoading='true';const result=await supabase.from('orders').select('delivery_address,user_id').eq('id',match[1]).maybeSingle();let address=result?.data?.delivery_address;if(result?.data?.user_id){const saved=await supabase.from('addresses').select('label,address_line,address,hotel_name,room_number').eq('user_id',result.data.user_id).order('created_at',{ascending:false});const rows=saved?.data||[];const matchByLabel=rows.find(row=>row.label&&row.label===result.data.delivery_address);const candidate=matchByLabel||rows.find(row=>(row.address_line||row.address)&&((row.address_line||row.address)!==result.data.delivery_address))||rows[0];if(candidate){const parts=[candidate.address_line||candidate.address,candidate.hotel_name,candidate.room_number&&`Room ${candidate.room_number}`].filter(Boolean);address=parts.join(' · ')||address}}if(address&&!modal.querySelector('.summary-address'))bill.insertAdjacentHTML('beforebegin',`<div class="summary-address"><span>Delivery address</span><strong>${escapeHtml(address)}</strong></div>`);modal.querySelectorAll('.summary-address').forEach((row,index)=>{if(index>0)row.remove()});modal.dataset.addressLoading='false'});orderSummaryAddressObserver.observe(document.body,{childList:true,subtree:true});
setInterval(()=>{const bill=document.querySelector('#order-summary-modal .summary-bill');if(bill&&!bill.parentElement.querySelector('.receipt-help-note'))bill.insertAdjacentHTML('afterend','<p class="receipt-help-note">For any discrepancy, issue, or question, please contact GroVale support.</p>')},700);
const orderSummaryProductImages=new MutationObserver(async()=>{const modal=document.querySelector('#order-summary-modal');if(!modal||modal.dataset.imagesLoaded==='true')return;const orderId=modal.querySelector('h2')?.textContent?.match(/#(.+)/)?.[1];if(!orderId)return;modal.dataset.imagesLoaded='true';const itemsResult=await supabase.from('order_items').select('product_name,product_id').eq('order_id',orderId);const items=itemsResult?.data||[];const ids=items.map(item=>item.product_id).filter(Boolean);const productsResult=ids.length?await supabase.from('products').select('id,name,image_url').in('id',ids):{data:[]};const products=productsResult?.data||[];modal.querySelectorAll('.summary-line').forEach(row=>{const name=row.querySelector('span')?.textContent?.split(' × ')[0];const item=items.find(value=>value.product_name===name);const product=products.find(value=>String(value.id)===String(item?.product_id));if(product?.image_url&&!row.querySelector('.summary-product-image'))row.insertAdjacentHTML('afterbegin',`<img class="summary-product-image" src="${escapeHtml(product.image_url)}" alt="${escapeHtml(product.name||name||'Product')}" loading="lazy">`)})});orderSummaryProductImages.observe(document.body,{childList:true,subtree:true});
setInterval(async()=>{const modal=document.querySelector('#order-summary-modal');if(!modal||modal.querySelector('.summary-product-image'))return;const orderId=modal.querySelector('h2')?.textContent?.match(/#(.+)/)?.[1];if(!orderId)return;const items=(await supabase.from('order_items').select('product_name,product_id').eq('order_id',orderId))?.data||[];const remoteProducts=(await supabase.from('products').select('id,name,image_url'))?.data||[];modal.querySelectorAll('.summary-line').forEach(row=>{const name=row.querySelector('span')?.textContent?.split(' × ')[0];const item=items.find(value=>value.product_name===name);const product=(products||[]).find(value=>value.name===name&&value.image_url)||remoteProducts.find(value=>String(value.id)===String(item?.product_id)||value.name===name);if(product?.image_url&&!row.querySelector('.summary-product-image'))row.insertAdjacentHTML('afterbegin',`<img class="summary-product-image" src="${escapeHtml(product.image_url)}" alt="${escapeHtml(product.name||name||'Product')}" loading="lazy">`)})},1200);
function adjustProduct(id,amount){const item=cart.find(x=>String(x.id)===String(id));if(!item)return;const product=products.find(p=>String(p.id)===String(id));if(amount>0&&product?.stock_quantity!=null&&item.qty>=Number(product.stock_quantity)){showToastMessage(`Only ${product.stock_quantity} left in stock`);return}item.qty+=amount;if(item.qty<=0){cart=cart.filter(x=>String(x.id)!==String(id))}save();const card=[...document.querySelectorAll('#subcategory-products .product')].find(node=>node.querySelector('h3')?.textContent===product?.name);if(card){const control=card.querySelector('.add, .qty');if(cart.find(x=>String(x.id)===String(id))){const qty=cart.find(x=>String(x.id)===String(id)).qty;control.outerHTML=`<div class="qty"><button onclick="adjustProduct('${id}',-1)">−</button><span>${qty}</span><button onclick="adjustProduct('${id}',1)">+</button></div>`}else{control.outerHTML=`<button class="add" onclick="add('${id}')">Add +</button>`}}const badge=document.querySelector('#cart .badge');if(badge)badge.textContent=cart.reduce((total,line)=>total+line.qty,0)}
function add(id){const product=products.find(p=>String(p.id)===String(id));if(!product)return;const item=cart.find(x=>String(x.id)===String(product.id));if(item)item.qty++;else cart.push({id:product.id,qty:1});save();const card=[...document.querySelectorAll('#subcategory-products .product')].find(node=>node.querySelector('h3')?.textContent===product.name);if(card){const button=card.querySelector('.add');if(button)button.outerHTML=`<div class="qty"><button onclick="adjustProduct('${product.id}',-1)">−</button><span>${cart.find(x=>String(x.id)===String(product.id)).qty}</span><button onclick="adjustProduct('${product.id}',1)">+</button></div>`}const badge=document.querySelector('#cart .badge');if(badge)badge.textContent=cart.reduce((total,line)=>total+line.qty,0);showToast();openCart()}
function changeProduct(id,amount){const item=cart.find(x=>x.id===id);if(item)item.qty+=amount;else if(amount>0)cart.push({id,qty:1});cart=cart.filter(item=>item.qty>0);save();if(document.querySelector('#checkout-overlay'))checkout(selectedDeliveryType);else bind()}
function showToast(){const total=cart.reduce((sum,item)=>sum+products.find(product=>product.id===item.id).price*item.qty,0);const toast=document.querySelector('#toast');if(toast){toast.classList.add('item-added-toast');toast.textContent=`${cart.reduce((sum,item)=>sum+item.qty,0)} item${cart.reduce((sum,item)=>sum+item.qty,0)===1?'':'s'} added · ${money(total)}`;toast.style.display='block';setTimeout(()=>toast.style.display='none',2200)}}
function cartTotals(){const totals=cart.reduce((result,item)=>{const product=products.find(p=>String(p.id)===String(item.id));if(!product)return result;const sellingPrice=Number(product.price||0),mrp=Number(product.mrp||sellingPrice);result.subtotal+=mrp*item.qty;result.afterDiscount+=sellingPrice*item.qty;return result},{subtotal:0,afterDiscount:0});const discount=Math.max(0,totals.subtotal-totals.afterDiscount);const delivery=cart.length?(totals.afterDiscount>=FREE_DELIVERY_THRESHOLD?0:DELIVERY_FEE):0;const handling=cart.length?HANDLING_FEE:0;return {...totals,discount,delivery,handling,grand:totals.afterDiscount+delivery+handling}}
function billMarkup(t){return `<div class="bill"><div><span>Subtotal</span><span>${money(t.subtotal)}</span></div><div><span>Discount</span><span>-${money(t.discount)}</span></div><div><span>Items total</span><span>${money(t.afterDiscount)}</span></div><div><span>Delivery</span><span>${t.delivery?money(t.delivery):'<small>FREE</small>'}</span></div><div><span>Service fee</span><span>${money(t.handling)}</span></div></div><div class="total"><span>Grand total</span><span>${money(t.grand)}</span></div>`}
function grandTotalMarkup(t){return `<div class="total checkout-grand-total"><span>Grand total</span><span>${money(t.grand)}</span></div>`}
function openCart(){const d=document.querySelector('#drawer'),p=document.querySelector('#drawer-panel');d.classList.add('open');const t=cartTotals();p.innerHTML=`<div class="drawer-head"><h2>Your cart</h2><button class="close" onclick="closeDrawer()">×</button></div>${cart.length?`<div class="cart-items-scroll">${cart.map(i=>{const x=products.find(p=>String(p.id)===String(i.id));const mrpTotal=Number(x.mrp||0)*i.qty;const priceTotal=Number(x.price||0)*i.qty;return `<div class="cart-row"><div class="mini">${x.emoji}</div><div class="cart-info"><strong>${x.name}</strong><small>${money(x.price)}${Number(x.mrp||0)>Number(x.price||0)?` <s class="cart-mrp">${money(x.mrp)}</s>`:''} each</small><div class="qty"><button onclick="change('${i.id}',-1)">−</button><span>${i.qty}</span><button onclick="change('${i.id}',1)">+</button></div></div><div class="cart-row-prices"><strong>${money(priceTotal)}</strong>${mrpTotal>priceTotal?`<s>${money(mrpTotal)}</s>`:''}</div></div>`}).join('')}</div><div class="cart-summary">${t.afterDiscount<FREE_DELIVERY_THRESHOLD?`<div class="free-delivery-hint">Add ${money(FREE_DELIVERY_THRESHOLD-t.afterDiscount)} more for free delivery.</div>`:''}${billMarkup(t)}<button class="checkout" onclick="checkout()">Continue to checkout</button></div>`:'<div class="empty empty-cart"><strong>Your cart is empty</strong><span>Browse categories to add products to your order.</span><button class="checkout" onclick="closeDrawer();document.querySelector(\'#category-hub\')?.scrollIntoView({behavior:\'smooth\',block:\'start\'})">Browse categories</button></div>'}`}
function closeDrawer(){const drawer=document.querySelector('#drawer');if(drawer){drawer.classList.remove('open');drawer.setAttribute('aria-hidden','true')}}
function change(id,n){const i=cart.find(x=>String(x.id)===String(id)),product=products.find(p=>String(p.id)===String(id));if(!i)return;if(n>0&&product?.stock_quantity!=null&&i.qty>=Number(product.stock_quantity)){showToastMessage(`Only ${product.stock_quantity} left in stock`);return}i.qty+=n;if(i.qty<=0)cart=cart.filter(x=>String(x.id)!==String(id));save();renderCartPanel()}
function showAuthModal(){if(document.querySelector('#auth-modal'))return;document.body.insertAdjacentHTML('beforeend',`<div class="auth-modal" id="auth-modal"><div class="auth-card"><button class="close" onclick="closeAuthModal()">×</button><div class="eyebrow">Welcome to GroVale</div><h2>Sign in</h2><p>Use your email address and password to continue.</p><input id="auth-email" type="email" autocomplete="email" required pattern="[^\\s@]+@[^\\s@]+\\.[^\\s@]+" oninput="this.setCustomValidity(this.validity.valid?'':'Enter a valid email address.')" placeholder="you@example.com"/><input id="auth-password" type="password" autocomplete="current-password" required minlength="6" placeholder="Password"/><button class="checkout" onclick="signInWithPassword()">Sign in</button><button class="text-button" onclick="closeAuthModal()">Continue browsing</button><div id="auth-message"></div></div></div>`)}
function closeAuthModal(){if(!currentUser)pendingOrderAfterAuth=false;document.querySelector('#auth-modal')?.remove()}
async function sendMagicLink(){const email=document.querySelector('#auth-email')?.value.trim();const message=document.querySelector('#auth-message');if(!email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){if(message)message.textContent='Enter a valid email address.';return}const button=document.querySelector('.auth-card .checkout');if(button){button.disabled=true;button.textContent='Sending…'}const {error}=await supabase.auth.signInWithOtp({email,options:{emailRedirectTo:`${location.origin}${location.pathname}`}});if(message){const raw=error?.message||'';message.textContent=raw.includes('over_email_send_rate_limit')||raw.includes('429')?'Email limit reached. Please wait before requesting another sign-in link.':error?'Unable to send the link. Please try again later.':'Check your email, then return to this page to finish signing in.'}if(button){button.textContent=error?'Try again later':'Link sent';if(error)setTimeout(()=>{button.disabled=false;button.textContent='Send sign-in link'},60000)}}
async function savePendingGuestAddress(){const pending=readStoredJson('pahalgam-pending-guest-address',null);if(!pending||!currentUser)return;const result=await supabase.from('addresses').insert({user_id:currentUser.id,label:pending.label||'Home',address_line:pending.address_line,district:pending.district,city:pending.city,state:pending.state,hotel_name:null,room_number:null,delivery_instructions:null});if(!result?.error)localStorage.removeItem('pahalgam-pending-guest-address');else console.warn('Guest address save unavailable:',result.error.message)}
async function signInWithPassword(){const email=document.querySelector('#auth-email')?.value.trim(),password=document.querySelector('#auth-password')?.value,message=document.querySelector('#auth-message'),button=document.querySelector('.auth-card .checkout');if(!email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){if(message)message.textContent='Enter a valid email address.';return}if(!password||password.length<6){if(message)message.textContent='Password must be at least 6 characters.';return}if(button){button.disabled=true;button.textContent='Signing in…'}const {error}=await supabase.auth.signInWithPassword({email,password});if(error){if(message)message.textContent=error.message?.toLowerCase().includes('invalid login credentials')?'Incorrect email or password.':'Unable to sign in. Please try again.';if(button){button.disabled=false;button.textContent='Sign in'}return}currentUser=await getCurrentUser();await savePendingGuestAddress();closeAuthModal();if(pendingOrderAfterAuth){pendingOrderAfterAuth=false;placeOrder()}else{await accountPage();restoreAccountHash()}}
window.signInWithPassword=signInWithPassword;
async function sendPhoneCode(){const phone=document.querySelector('#auth-phone')?.value.trim();if(!phone)return;const {error}=await sendPhoneOtp(phone);const message=document.querySelector('#auth-message');if(error){message.textContent=error.message;return}document.querySelector('#pin-step').style.display='block';message.textContent='PIN sent. Check your phone.'}
async function verifyPhoneCode(){const phone=document.querySelector('#auth-phone')?.value.trim();const pin=document.querySelector('#auth-pin')?.value.trim();if(!phone||!pin)return;const {error}=await verifyPhoneOtp(phone,pin);const message=document.querySelector('#auth-message');if(error){message.textContent=error.message;return}currentUser=await getCurrentUser();await savePendingGuestAddress();closeAuthModal();if(pendingOrderAfterAuth){pendingOrderAfterAuth=false;placeOrder();}else{alert('Signed in successfully.');}}
async function accountAction(){
  if(!currentUser){showAuthModal();return}
  document.querySelector('#app').innerHTML=`${header()}<main class="main"><div class="eyebrow account-page-label">Your account</div><h2>Loading your account…</h2></main>`;
  await accountPage();
}
async function accountPage(){
  const timed=(query,ms=7000)=>Promise.race([query,new Promise(resolve=>setTimeout(()=>resolve({data:null,error:new Error('timeout')}),ms))]);
  const [profileResult,ordersResult,addressesResult]=await Promise.all([
    timed(loadCurrentProfile()),
    timed(supabase.from('orders').select('*').eq('user_id',currentUser.id).order('created_at',{ascending:false})),
    timed(supabase.from('addresses').select('*').eq('user_id',currentUser.id).order('created_at',{ascending:false}))
  ]);
  const profile=profileResult?.data||{};
  window.currentProfile=profile;
  const orders=Array.isArray(ordersResult?.data)?ordersResult.data:[];
  const addresses=Array.isArray(addressesResult?.data)?addressesResult.data:[];
  document.querySelector('#app').innerHTML=`${header()}<main class="main"><div class="account-top-actions"><button class="pill-btn" onclick="goHome()">← Home</button><button class="pill-btn" onclick="goBack()">← Back</button></div><div class="eyebrow account-page-label">Your account</div><div class="section-head"><div><h2>${escapeHtml(profile.full_name||profile.name||profile.display_name||currentUser.user_metadata?.full_name||currentUser.user_metadata?.name||'Customer')}</h2><p class="muted">${escapeHtml(currentUser.email)}</p></div></div><div class="form-card order-history"><h2>Order history</h2>${orders.length?orders.map(order=>`<div class="cart-row"><div class="cart-info"><strong>Order #${escapeHtml(order.id)}</strong>${order.status==='cancelled'&&order.delivery_failure_reason?`<small class="cancel-note">Cancellation note: ${escapeHtml(order.delivery_failure_reason)}</small>`:''}</div><div class="order-history-actions"><strong>${money(Number(order.total||0))}</strong>${['pending','confirmed'].includes(order.status)?`<button class="text-button cancel-order-button" onclick="cancelCustomerOrder('${escapeHtml(order.id)}')">Cancel order</button>`:''}</div></div>`).join(''):'<div class="empty">Your orders will appear here.</div>'}</div><div class="form-card saved-addresses"><h2>Saved delivery details</h2>${addresses.length?addresses.map(address=>`<div class="cart-row"><div class="cart-info"><strong>${escapeHtml(address.label||'Saved address')}</strong><small>${escapeHtml(address.address_line||address.address||'')}</small></div></div>`).join(''):'<div class="empty">Saved addresses will appear after your first order.</div>'}</div></main>`;
  document.querySelector('#cart').onclick=openCart;document.querySelector('#account').onclick=toggleAccountMenu;decorateAccountPage();populateProfileDetails();addAddressLink();decorateSavedAddresses(addresses);groupOrderHistoryByDate(orders);decorateOrderTracking(orders);loadOrderHistoryItems(orders);
}
let floatingOrderTimer;async function refreshFloatingOrderStatus(){if(!currentUser)return;const result=await supabase.from('orders').select('*').eq('user_id',currentUser.id).order('created_at',{ascending:false}).maybeSingle();const order=result?.data;let box=document.querySelector('#floating-order-status');if(!order){box?.remove();return}if(!box){document.body.insertAdjacentHTML('beforeend','<aside id="floating-order-status" class="floating-order-status" aria-live="polite"></aside>');box=document.querySelector('#floating-order-status')}const labels={pending:'Order received',confirmed:'Confirmed by merchant',preparing:'Being prepared',ready_for_delivery:'Ready for rider',out_for_delivery:'Out for delivery',delivered:'Delivered',cancelled:'Not delivered'};const icons={pending:'🧾',confirmed:'✓',preparing:'🍳',ready_for_delivery:'📦',out_for_delivery:'🚴',delivered:'🏠',cancelled:'⚠️'};box.innerHTML=`<button class="floating-order-close" aria-label="Close order status">×</button><span class="eyebrow">Live order status</span><strong>${icons[order.status]||'📦'} ${labels[order.status]||'Order update'}</strong><small>Order #${escapeHtml(order.id)} · ${money(Number(order.total||0))}</small><button class="pill-btn floating-order-link" onclick="accountMenuAction('orders')">View my orders →</button>`;box.querySelector('.floating-order-close').onclick=()=>{box.remove();sessionStorage.setItem('hide-floating-order',String(order.id))};if(sessionStorage.getItem('hide-floating-order')===String(order.id))box.remove()}
function startFloatingOrderStatus(){clearInterval(floatingOrderTimer);refreshFloatingOrderStatus();floatingOrderTimer=setInterval(refreshFloatingOrderStatus,15000)}
function decorateOrderTracking(orders){const statuses=['pending','confirmed','preparing','ready_for_delivery','out_for_delivery','delivered'],icons=['🧾','✓','🍳','📦','🚴','🏠'];document.querySelectorAll('.order-history .cart-row').forEach((row,index)=>{const order=orders[index];if(!order||['delivered','cancelled'].includes(order.status)||row.querySelector('.order-tracking'))return;const current=statuses.indexOf(typeof order.status==='string'?order.status:'pending'),timeline=statuses.map((status,step)=>`<span class="${step<=current?'done':''} ${step===current?'current':''}"><i>${icons[step]}</i><b>${customerStatusLabel(status)}</b></span>`).join('');const rider=orderRiderMarkup(order);row.insertAdjacentHTML('beforeend',`<div class="order-tracking"><div class="tracking-title">Delivery progress</div><div class="status-timeline">${timeline}</div>${rider}<a class="help-link" href="mailto:hello@grovale.in?subject=Help with order ${encodeURIComponent(order.id)}">Need help?</a></div>`)})}
function groupOrderHistoryByDate(orders){const card=document.querySelector('.order-history');if(!card||card.dataset.grouped)return;card.dataset.grouped='true';const rows=[...card.querySelectorAll('.cart-row')];let groups=[];rows.forEach((row,index)=>{const date=orders[index]?.created_at?new Date(orders[index].created_at).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'}):'Older orders';let group=groups.find(item=>item.date===date);if(!group){group={date,rows:[]};groups.push(group)}group.rows.push(row)});rows.forEach(row=>row.remove());groups.forEach((group,index)=>{const details=document.createElement('details');details.className='order-date-group';details.open=index===0;details.innerHTML=`<summary>${group.date}<span>${group.rows.length} order${group.rows.length===1?'':'s'}</span></summary>`;group.rows.forEach(row=>details.appendChild(row));card.appendChild(details)})}
function populateProfileDetails(){const table=document.querySelector('#account-profile .details-table');if(!table||table.dataset.complete)return;table.dataset.complete='true';const profile=window.currentProfile||{};table.insertAdjacentHTML('beforebegin','<button class="pill-btn edit-profile" onclick="editProfile()">Edit profile</button>');table.insertAdjacentHTML('beforeend',`<div><span>Phone</span><strong>${escapeHtml(profile.phone||currentUser.phone||'Not added')}</strong></div><div><span>Default address</span><strong>${escapeHtml(currentUser.user_metadata?.default_address||'Choose from My addresses')}</strong></div><div><span>Account type</span><strong>Customer</strong></div><div><span>Notifications</span><strong>Email notifications enabled</strong></div><div><span>Sign-in settings</span><strong>Email link sign-in</strong></div><div><span>Account created</span><strong>${currentUser.created_at?new Date(currentUser.created_at).toLocaleDateString():'Not available'}</strong></div>`)}
