function decorateSavedAddresses(addresses){document.querySelectorAll('.saved-addresses .cart-row').forEach((row,index)=>{const address=addresses[index];if(!address)return;const detail=row.querySelector('.cart-info small');if(detail)detail.textContent=addressDetails(address);const actions=document.createElement('div');actions.className='saved-address-actions';actions.innerHTML=`<button type="button" class="text-button modify-saved-address">Modify</button><button type="button" class="text-button delete-saved-address">Delete</button>`;actions.querySelector('.modify-saved-address').onclick=event=>{event.preventDefault();event.stopPropagation();modifySavedAddress(address)};actions.querySelector('.delete-saved-address').onclick=event=>{event.preventDefault();event.stopPropagation();deleteSavedAddress(address.id)};row.appendChild(actions);row.setAttribute('role','button');row.setAttribute('tabindex','0');row.setAttribute('aria-label',`Use ${address.label||'saved address'} for delivery`);row.onclick=()=>selectSavedAddress(address,row);row.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();selectSavedAddress(address,row)}};const saved=JSON.parse(localStorage.getItem('pahalgam-last-delivery')||'null');if(saved?.address===address.address_line)row.classList.add('selected')})}
async function modifySavedAddress(address){addNewAddress();const modal=document.querySelector('#address-modal');if(!modal)return;modal.dataset.simplified='true';modal.dataset.editingAddressId=address.id;const set=(id,value)=>{const field=modal.querySelector(id);if(field)field.value=value||''};const storedLine=String(address.address_line||address.address||'');const lane=storedLine.split(',')[0].trim();const profile=window.currentProfile||{};set('#new-address-label',address.label==='Home'?'':address.label);set('#new-address-name',profile.full_name||profile.name||currentUser.user_metadata?.full_name||currentUser.user_metadata?.name||'');set('#new-address-line',lane);set('#new-address-district',address.district);set('#new-address-city',address.city);set('#new-address-state',address.state||'Jammu and Kashmir');set('#new-address-phone',profile.phone||currentUser.phone||'');const button=modal.querySelector('button.checkout');if(button)button.textContent='Update address';const heading=modal.querySelector('h2');if(heading)heading.textContent='Modify address';button.onclick=updateExistingSavedAddress}
const originalSaveNewAddress=saveNewAddress;saveNewAddress=async function(button){const modal=document.querySelector('#address-modal'),id=modal?.dataset.editingAddressId;if(!id){return originalSaveNewAddress(button)}const val=selector=>modal.querySelector(selector)?.value.trim()||'';const label=val('#new-address-label')||'Home',line=val('#new-address-line'),district=val('#new-address-district'),city=val('#new-address-city'),state=val('#new-address-state'),phone=val('#new-address-phone'),name=val('#new-address-name'),message=modal.querySelector('#address-message');if(!name||!line||!district||!city||!state||!/^[6-9][0-9]{9}$/.test(phone)){if(message)message.textContent='Complete your name, address, state, and valid phone number.';return}if(button){button.disabled=true;button.textContent='Updating…'}const oldResult=await supabase.from('addresses').select('address_line').eq('id',id).eq('user_id',currentUser.id).maybeSingle();const previousLine=oldResult?.data?.address_line||'';const result=await supabase.from('addresses').update({label,address_line:[line,district,city,state].join(', '),district,city,state}).eq('id',id).eq('user_id',currentUser.id);if(result?.error){if(message)message.textContent=result.error.message;if(button){button.disabled=false;button.textContent='Update address'}return}if(previousLine){const duplicates=await supabase.from('addresses').select('id').eq('user_id',currentUser.id).eq('address_line',previousLine);for(const duplicate of (duplicates?.data||[])){if(String(duplicate.id)!==String(id))await supabase.from('addresses').delete().eq('id',duplicate.id).eq('user_id',currentUser.id)}}await supabase.from('profiles').update({full_name:name,phone,updated_at:new Date().toISOString()}).eq('id',currentUser.id);document.querySelector('#address-modal')?.remove();await accountPage()};window.saveNewAddress=saveNewAddress;
