async function loadOrderHistoryItems(orders){try{const result=await supabase.from('order_items').select('*');const items=Array.isArray(result?.data)?result.data:[];document.querySelectorAll('.order-history .cart-row').forEach((row,index)=>{const order=orders[index];if(!order)return;const lines=items.filter(item=>String(item.order_id)===String(order.id)).map(item=>`${escapeHtml(item.product_name||'Product')} × ${item.quantity}`).join(' · ');if(lines){const amount=row.querySelector('.cart-info')?.parentElement?.lastElementChild;if(amount){amount.insertAdjacentHTML('afterend',`<button class="order-summary-link" onclick="showOrderSummary('${escapeHtml(order.id)}', this.dataset.orderAddress)">Order summary</button>`);const button=amount.parentElement?.querySelector('.order-summary-link');if(button)button.dataset.orderAddress=[order.delivery_address,order.hotel_name,order.business_name,order.room_number?`Room ${order.room_number}`:''].filter(Boolean).join(' · ')}}})}catch(error){console.warn('Order items unavailable:',error.message)}}
async function showOrderSummary(orderId,historyAddress=''){const [itemsResult,orderResult]=await Promise.all([supabase.from('order_items').select('*'),supabase.from('orders').select('*').eq('id',orderId).maybeSingle()]);const items=(itemsResult?.data||[]).filter(item=>String(item.order_id)===String(orderId));const order=orderResult?.data||{};const riderResult=order.rider_id?await supabase.from("profiles").select("full_name,phone,profile_photo_url").eq("id",order.rider_id).maybeSingle():{data:null};const rider=riderResult?.data||{};const address=[order.delivery_address,order.hotel_name,order.business_name,order.room_number?`Room ${order.room_number}`:''].filter(Boolean).join(' · ')||historyAddress;const status=customerStatusLabel(order.status);const subtotal=Number(order.subtotal||items.reduce((sum,item)=>sum+Number(item.line_total||0),0));const delivery=Number(order.delivery_fee||0);const total=Number(order.total||subtotal+delivery+HANDLING_FEE);const discount=Math.max(0,subtotal+delivery+HANDLING_FEE-total);document.querySelector('#order-summary-modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="auth-modal" id="order-summary-modal" onclick="if(event.target.id==='order-summary-modal')this.remove()"><div class="auth-card order-summary-card"><button class="close" onclick="this.closest('#order-summary-modal').remove()">×</button><div class="receipt-brand"><span class="receipt-brand-gro">Gro</span><span class="receipt-brand-vale">Vale</span><small>Order receipt</small></div><div class="eyebrow">Order summary</div><h2>Order #${escapeHtml(orderId)} <span class="summary-status summary-status-${escapeHtml(order.status||'pending')}">${escapeHtml(status)}</span></h2>${order.created_at?`<small class="summary-date">${new Date(order.created_at).toLocaleString()}</small>`:''}${items.length?items.map(item=>`<div class="summary-line"><span>${escapeHtml(item.product_name||'Product')} × ${item.quantity}</span><strong>${money(Number(item.line_total||0))}</strong></div>`).join(''):'<div class="empty">Order items are unavailable.</div>'}${address?`<div class="summary-address"><span>Delivery address</span><strong>${escapeHtml(address)}</strong></div>`:''}${orderSummaryRiderMarkup(rider)}<div class="summary-bill"><div><span>Subtotal</span><span>${money(subtotal)}</span></div><div><span>Discount</span><span>-${money(discount)}</span></div><div><span>Delivery</span><span>${delivery?money(delivery):'FREE'}</span></div><div><span>Service fee</span><span>${money(HANDLING_FEE)}</span></div><div class="summary-grand"><strong>Grand total</strong><strong>${money(total)}</strong></div></div><div class="summary-bottom-actions"><button class="checkout" onclick="this.closest('#order-summary-modal').remove()">Close</button><button class="text-button summary-reorder" onclick="reorderOrder('${escapeHtml(orderId)}',this)">Re-order</button></div></div></div>`)}
