function decorateAccountPage(){const main=document.querySelector('#app .main');if(!main||main.querySelector('.account-sidebar'))return;const profile=main.querySelector('.section-head');const savedProfile=window.currentProfile||{};profile?.classList.add('account-header');const orders=main.querySelector('.order-history');const addresses=main.querySelector('.saved-addresses');orders?.setAttribute('id','account-orders');addresses?.setAttribute('id','account-addresses');main.insertAdjacentHTML('afterbegin',`<aside class="account-sidebar"><div class="eyebrow">Account</div><nav><button class="active" onclick="showAccountSection('account-profile',this)">Profile</button><button onclick="showAccountSection('account-orders',this)">My orders</button><button onclick="showAccountSection('account-addresses',this)">My addresses</button><button onclick="showAccountSection('account-prescriptions',this)">My prescriptions</button><button class="logout-option" onclick="signOut()">Logout</button></nav></aside>`);main.insertAdjacentHTML('beforeend',`<section class="form-card account-section" id="account-profile"><h2>Profile</h2><div class="details-table"><div><span>Email</span><strong>${escapeHtml(savedProfile.email||currentUser.email)}</strong></div><div><span>Name</span><strong>${escapeHtml(savedProfile.full_name||'Not added')}</strong></div></div></section><section class="form-card account-section" id="account-prescriptions"><h2>My prescriptions</h2><div class="empty">No prescriptions have been added yet.</div></section>`)}
