async function reorderOrder(id,button){if(button){button.disabled=true;button.textContent='Loading…'}const result=await supabase.from('order_items').select('*').eq('order_id',id),items=result.data||[];let added=0;items.forEach(item=>{const product=products.find(entry=>String(entry.id)===String(item.product_id));if(!product||!productIsAvailable(product))return;const existing=cart.find(entry=>String(entry.id)===String(product.id));if(existing)existing.qty+=Number(item.quantity||1);else cart.push({id:product.id,qty:Number(item.quantity||1)});added+=Number(item.quantity||1)});save();if(button){button.disabled=false;button.textContent=added?'Added to cart':'Items unavailable'}if(added){document.querySelector("#order-summary-modal")?.remove();const badge=document.querySelector("#cart .badge");if(badge)badge.textContent=cart.reduce((total,line)=>total+line.qty,0);showToastMessage(`${added} item${added===1?'':'s'} added from order #${id}`);setTimeout(openCart,0)}else showToastMessage('The items from this order are no longer available.')}

async function signOut(){const user=currentUser;try{if(user){const cartResult=await supabase.from("carts").select("id").eq("user_id",user.id).maybeSingle();const cartId=cartResult?.data?.id;if(cartId)await supabase.from("cart_items").delete().eq("cart_id",cartId)}}catch(error){console.warn("Cloud cart cleanup unavailable:",error.message)}cart=[];localStorage.removeItem("pahalgam-cart");await supabase.auth.signOut();currentUser=null;render()}
function fieldKey(type,field){if(field==='Name'||field==='Guest name'||field==='Contact person')return'customer_name';if(field==='Village/Town')return'village_town';if(field==='Hotel name')return type==='hotel_guest'?'hotel_name':'business_name';if(field==='Restaurant name')return'business_name';if(field==='Phone number')return'phone';if(field==='Lane/House/Street'||field==='Business address')return'delivery_address';if(field==='Room number')return'room_number';if(field==='Preferred delivery slot')return'delivery_slot';return'delivery_instructions'}
function fieldMarkup(type,field,i,saved){const value=escapeHtml(saved[fieldKey(type,field)]||'');const full=i===types[type].fields.length-1?'full':'';if(field==='Preferred delivery slot')return `<div class="field"><label>${field}</label><select data-field="${field}" onchange="validateCheckoutField(this)"><option value="">Choose a time</option>${deliverySlots.map(slot=>`<option value="${slot}" ${value===slot?'selected':''}>${slot}</option>`).join('')}</select></div>`;if(field==='Order notes'||field==='Delivery instructions')return `<div class="field ${full}"><label>${field}</label><textarea data-field="${field}" maxlength="300" oninput="validateCheckoutField(this)" placeholder="${field==='Order notes'?'Example: Please call on arrival and leave at the kitchen door.':'Example: Ring the bell at reception.'}">${value}</textarea></div>`;const phone=field==='Phone number';const person=['Name','Guest name','Contact person','Hotel name','Restaurant name'].includes(field);const address=['Lane/House/Street','Village/Town','Business address'].includes(field);const room=field==='Room number';const pattern=phone?'[6-9][0-9]{9}':person?'[A-Za-zÀ-ÿ][A-Za-zÀ-ÿ .\'-]{1,59}':room?'[A-Za-z0-9 /-]{1,20}':'';const live=phone?"this.value=this.value.replace(/[^0-9]/g,'');validateCheckoutField(this)":'validateCheckoutField(this)';const input=`<input data-field="${field}" value="${value}" type="${phone?'tel':'text'}" required maxlength="${address?'160':phone?'10':room?'20':'80'}" ${pattern?`pattern="${pattern}"`:''} ${phone?'inputmode="numeric"':''} oninput="${live}" placeholder="Enter ${field.toLowerCase()}" />`;return `<div class="field ${full}"><label>${field} *</label>${address?`<div class="address-input">${input}<button type="button" class="locate" onclick="detectLocation()">⌖ Use my location</button></div>`:input}</div>`}
function escapeHtml(value=''){return String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}
function addressDetails(address){const details=[address.address_line||address.address,address.hotel_name,address.room_number&&`Room ${address.room_number}`,address.delivery_instructions].filter(Boolean).map(escapeHtml);return details.join(' · ')||'No address details saved.'}
function validateCheckoutField(field){const value=field.value.trim();const name=field.dataset.field;let message='';if(field.tagName==='SELECT')message=value?'':'Choose a delivery time.';else if(field.required&&!value)message=`${name} is required.`;else if(name==='Phone number'&&!/^[6-9][0-9]{9}$/.test(value))message='Enter exactly 10 digits starting with 6–9.';else if(['Name','Guest name','Contact person','Hotel name','Restaurant name'].includes(name)&&!/^[A-Za-zÀ-ÿ][A-Za-zÀ-ÿ .'-]{1,59}$/.test(value))message='Use letters, spaces, apostrophes, or hyphens only.';field.setCustomValidity(message);field.classList.toggle('field-error',Boolean(message));return !message}
async function checkout(type=selectedDeliveryType){if(!cart.length){openCart();return}selectedDeliveryType=type;closeDrawer();const fields=types[type].fields;const t=cartTotals();let saved={};if(currentUser){try{const result=await Promise.race([Promise.all([supabase.from('saved_delivery_profiles').select('*').eq('user_id',currentUser.id).eq('order_type',type).maybeSingle(),supabase.from('addresses').select('*').eq('user_id',currentUser.id).order('created_at',{ascending:false}).maybeSingle(),loadCurrentProfile()]),new Promise(resolve=>setTimeout(()=>resolve([{data:null},{data:null},{data:null}],7000)))]);const profile=result?.[0]?.data||{};const address=result?.[1]?.data||{};const customer=result?.[2]?.data||{};const accountProfile=window.currentProfile||{};const addressLine=address.address_line||address.address||'';saved={...profile,customer_name:profile.customer_name||customer.full_name||accountProfile.full_name||currentUser.user_metadata?.full_name||'',phone:profile.phone||customer.phone||accountProfile.phone||currentUser.phone||'',delivery_address:profile.delivery_address||addressLine,village_town:profile.village_town||address.village_town||'Pahalgam',hotel_name:profile.hotel_name||address.hotel_name,room_number:profile.room_number||address.room_number,delivery_instructions:profile.delivery_instructions||address.delivery_instructions};}catch(error){console.warn('Saved delivery details unavailable:',error.message)}}
  const review=checkoutStep===1;window.currentSavedCheckout=saved;
  document.querySelector('#checkout-overlay')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="checkout-overlay" id="checkout-overlay"><div class="checkout-sheet"><div class="checkout-steps"><span class="active">1 Review</span><i></i><span class="${review?'':'active'}">2 Details</span><i></i><span class="${review?'':'active'}">3 Confirm</span></div><div class="drawer-head"><div><div class="eyebrow">${review?'Cart review':'Checkout'} · ${types[type].label}</div><h2>${review?'Review your order':'Place your order'}</h2></div><button class="close" onclick="closeCheckout()">×</button></div>${review?`${checkoutItemsMarkup()}<div class="checkout-summary">${billMarkup(t)}</div><button class="checkout" style="margin-top:22px" onclick="continueToCheckout()">Continue to checkout</button>`:`<div class="checkout-summary">${billMarkup(t)}<div class="cod-summary">💵 Cash on delivery · Pay when your order arrives</div></div><div class="delivery-type-row"><label>Order type</label><select id="delivery-type" onchange="checkout(this.value)">${Object.entries(types).map(([key,value])=>`<option value="${key}" ${key===type?'selected':''}>${value.icon} ${value.label}</option>`).join('')}</select></div>${saved.id?'<div class="saved-profile-note">Saved delivery details found. <button type="button" class="text-button" onclick="applySavedCheckoutDetails()">Use saved address</button></div>':''}<div id="checkout-form" class="fields" style="margin-top:16px"><div class="checkout-section-label">Delivery details</div>${fields.map((f,i)=>fieldMarkup(type,f,i,saved)).join('')}<div class="field full"><label>Payment method</label><div class="payment-options"><label><input type="radio" name="payment-method" value="cash_on_delivery" checked /> Cash on delivery</label></div><small class="checkout-note">Online payment will be added in a future update.</small></div></div><button class="checkout" style="margin-top:22px" onclick="placeOrder(this)">Place order · ${money(t.grand)}</button><button class="text-button checkout-back" onclick="backToCart()">← Back to cart</button>`}</div></div>`);document.querySelector('#checkout-overlay').addEventListener('click',event=>{if(event.target.id==='checkout-overlay')closeCheckout()});}
function applySavedCheckoutDetails(){const saved=window.currentSavedCheckout||{};document.querySelectorAll('#checkout-form [data-field]').forEach(input=>{const value=saved[fieldKey(selectedDeliveryType,input.dataset.field)]||'';if(value)input.value=value});showToastMessage('Saved delivery details applied.');}
function isJammuKashmirPin(pin){return /^(18|19)[0-9]{4}$/.test(String(pin||'').trim())}
function continueToCheckout(){
  if(cartTotals().grand<MIN_ORDER_AMOUNT){showToastMessage(`Minimum order amount is ${money(MIN_ORDER_AMOUNT)}.`);return}
  if(!currentUser&&!document.querySelector('#delivery-pin-modal')){
    document.body.insertAdjacentHTML('beforeend','<div class="auth-modal" id="delivery-pin-modal"><div class="auth-card"><button class="close" onclick="this.closest(\'#delivery-pin-modal\').remove()">×</button><div class="eyebrow">Delivery availability</div><h2>Check your PIN code</h2><p>Enter your Jammu & Kashmir PIN code to confirm delivery before checkout.</p><input id="delivery-pin-input" inputmode="numeric" maxlength="6" placeholder="6-digit PIN code" oninput="this.value=this.value.replace(/[^0-9]/g,\'\')" /><button class="checkout" onclick="confirmDeliveryPin()">Check availability</button><div id="delivery-pin-message" role="status"></div></div></div>');
    document.querySelector('#delivery-pin-input')?.focus();
    return;
  }
  checkoutStep=2;checkout(selectedDeliveryType)
}
function confirmDeliveryPin(){
  const input=document.querySelector('#delivery-pin-input'),message=document.querySelector('#delivery-pin-message'),pin=input?.value.trim()||'';
  if(!/^\d{6}$/.test(pin)){if(message)message.textContent='Enter a 6-digit PIN code.';return}
  if(!isJammuKashmirPin(pin)){if(message)message.textContent='Sorry, we don’t deliver to this area yet. We’re working on expanding our delivery service there soon.';return}
  localStorage.setItem('pahalgam-delivery-pin',pin);
  if(message){message.textContent='Yes, we deliver to your area.';message.style.color='var(--green)'}
  setTimeout(()=>{document.querySelector('#delivery-pin-modal')?.remove();checkoutStep=2;checkout(selectedDeliveryType)},1000)
}
function backToCart(){checkoutStep=1;checkout(selectedDeliveryType)}
function checkoutItemsMarkup(){return `<div class="checkout-items"><div class="checkout-items-head"><strong>Your cart</strong><span>${cart.reduce((sum,item)=>sum+item.qty,0)} items</span></div>${cart.map(item=>{const product=products.find(entry=>String(entry.id)===String(item.id));const priceTotal=Number(product.price||0)*item.qty;const mrpTotal=Number(product.mrp||0)*item.qty;return `<div class="checkout-item"><div class="checkout-item-image">${productImageMarkup(product)}</div><div class="checkout-item-details"><strong>${escapeHtml(product.name)}</strong><small>${money(product.price)} · ${escapeHtml(product.unit||'each')}</small><div class="qty"><button type="button" onclick="changeProduct('${product.id}',-1)">−</button><span>${item.qty}</span><button type="button" onclick="changeProduct('${product.id}',1)">+</button></div></div><div class="cart-row-prices"><strong>${money(priceTotal)}</strong>${mrpTotal>priceTotal?`<s>${money(mrpTotal)}</s>`:''}</div></div>`}).join('')}</div>`}
function detectLocation(){const input=document.querySelector('[data-field="Lane/House/Street"], [data-field="Business address"]');if(!input)return;if(!navigator.geolocation){input.placeholder='Please enter your address manually.';return}input.value='Detecting location…';navigator.geolocation.getCurrentPosition(position=>{input.value=`Near ${position.coords.latitude.toFixed(5)}, ${position.coords.longitude.toFixed(5)} — please add your hotel, room, or landmark.`},()=>{input.value='';input.placeholder='Location unavailable — enter your address manually.'},{enableHighAccuracy:true,timeout:10000});}
function closeCheckout(){checkoutStep=1;document.querySelector('#checkout-overlay')?.remove()}
async function placeOrder(button){
  if(button){button.disabled=true;button.textContent='Placing order…'}
  const failSafe=setTimeout(()=>{if(button?.disabled){button.disabled=false;button.textContent=`Place order · ${money(cartTotals().grand)}`;const note=document.querySelector('.checkout-note');if(note)note.textContent='Could not place order: The order service did not respond. Please try again.'}},15000);
  const type='individual';
  const inputs=[...document.querySelectorAll('#checkout-form [data-field]')];
  const values=inputs.map(input=>input.value.trim());
  const invalid=inputs.find(input=>!validateCheckoutField(input));
  if(invalid){invalid.reportValidity();if(button){button.disabled=false;button.textContent=`Place order · ${money(cartTotals().grand)}`}return}
  const required=inputs.filter(input=>!['Delivery instructions','Order notes'].includes(input.dataset.field));
  const missing=required.find(input=>!input.value);
  if(missing){missing.focus();missing.classList.add('field-error');if(button){button.disabled=false;button.textContent=`Place order · ${money(cartTotals().grand)}`}const note=document.querySelector('.checkout-note');if(note)note.textContent=`Please enter ${missing.dataset.field.toLowerCase()} before placing the order.`;return}
  if(!currentUser){if(button){button.disabled=false;button.textContent=`Place order · ${money(cartTotals().grand)}`}pendingOrderAfterAuth=true;showAuthModal();return}
  const [first,second,third,fourth,fifth]=values;
  const t=cartTotals();
  const total=t.grand;
  const customerName=type==='hotel_essentials'||type==='restaurant_supplies'?second:first;
  const addressDetails='';
  const order={user_id:currentUser.id,order_type:type,customer_name:customerName,phone:type==='individual'?second:(type==='hotel_guest'?second:third),delivery_address:type==='individual'?third:(type==='hotel_guest'?third:fourth),hotel_name:type==='hotel_guest'?third:null,room_number:type==='hotel_guest'?fourth:null,business_name:type==='hotel_essentials'||type==='restaurant_supplies'?first:null,delivery_slot:type==='hotel_essentials'||type==='restaurant_supplies'?fifth:null,delivery_instructions:type==='individual'?'':(type==='hotel_guest'?fifth:values[values.length-1]),status:'pending',subtotal:t.subtotal,delivery_fee:t.delivery,total};
  let error,orderId;
  try{const result=await Promise.race([supabase.from('orders').insert(order).select('id').single(),new Promise(resolve=>setTimeout(()=>resolve({data:null,error:new Error('The order service timed out. Please try again.')}),10000))]);error=result?.error;orderId=result?.data?.id}catch(requestError){error=requestError}
  if(!error&&!orderId){try{const lookup=await Promise.race([supabase.from('orders').select('id').eq('user_id',currentUser.id).order('created_at',{ascending:false}).single(),new Promise(resolve=>setTimeout(()=>resolve({data:null,error:new Error('The database did not return an order number.')}),3000))]);orderId=lookup?.data?.id;error=lookup?.error}catch(lookupError){error=lookupError}}
  if(error||!orderId){if(button){button.disabled=false;button.textContent=`Place order · ${money(cartTotals().grand)}`}const note=document.querySelector('.checkout-note');if(note)note.textContent=`Could not place order: ${error?.message||'The database did not return an order number. Please try again.'}`;return}
  const items=cart.map(item=>{const product=products.find(p=>p.id===item.id);return {order_id:orderId,product_id:product.id,product_name:product.name,unit_price:product.price,quantity:item.qty,line_total:product.price*item.qty}});
  const itemResult=await Promise.race([supabase.from('order_items').insert(items),new Promise(resolve=>setTimeout(()=>resolve({error:new Error('Order saved, but order items timed out.')}),8000))]);
  const itemError=itemResult?.error;
  if(itemError){alert(`Order created, but items need attention: ${itemError.message}`);return}
  const stockResult=await supabase.rpc('decrement_product_stock',{items:items.map(item=>({product_id:item.product_id,quantity:item.quantity}))});
  if(stockResult?.error){await supabase.from('orders').update({status:'cancelled'}).eq('id',orderId);if(button){button.disabled=false;button.textContent=`Place order · ${money(cartTotals().grand)}`}const message=stockResult.error.message.includes('Insufficient stock')?'Some items are no longer available in the requested quantity.':'Could not reserve stock. Please try again.';showToastMessage(message);const note=document.querySelector('.checkout-note');if(note)note.textContent=message;return}
  void sendOrderConfirmation({order_id:orderId,email:currentUser.email,order,total,items});
const address=order.delivery_address;if(address)localStorage.setItem('pahalgam-last-delivery',JSON.stringify({address,label:order.hotel_name&&order.room_number?`${order.hotel_name} · Room ${order.room_number}`:address}));
  if(address&&currentUser.id)void supabase.from('addresses').insert({user_id:currentUser.id,address_line:address,hotel_name:order.hotel_name,room_number:order.room_number,delivery_instructions:order.delivery_instructions,label:`${types[type].label} address`}).catch(error=>console.warn('Address save unavailable:',error.message));
  void supabase.from('saved_delivery_profiles').upsert({user_id:currentUser.id,order_type:type,customer_name:customerName,phone:order.phone,delivery_address:address,hotel_name:order.hotel_name,room_number:order.room_number,business_name:order.business_name,delivery_slot:order.delivery_slot,delivery_instructions:order.delivery_instructions,updated_at:new Date().toISOString()},{onConflict:'user_id,order_type'}).catch(error=>console.warn('Delivery profile save unavailable:',error.message));
  clearTimeout(failSafe);cart=[];save();closeCheckout();showOrderConfirmation(orderId,type,total,customerName);render();
}
function showOrderConfirmation(orderId,type,total,customerName='Customer'){document.querySelector('#order-confirmation')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="confirmation-overlay" id="order-confirmation"><div class="confirmation-card"><div class="confirmation-icon">✓</div><div class="eyebrow">Order confirmed</div><h2>Your delivery is on its way.</h2><p class="confirmation-lead">Thank you ${escapeHtml(customerName)}. We’ve received your ${types[type].label.toLowerCase()} order and will contact you before delivery.</p><div class="confirmation-details"><div><span>Order number</span><strong>#${orderId}</strong></div><div><span>Order total</span><strong>${money(total)}</strong></div><div><span>Payment</span><strong>Cash on delivery</strong></div><div><span>Status</span><strong>Preparing your order</strong></div></div><button class="checkout" onclick="closeConfirmation()">Continue browsing</button><button class="text-button" onclick="accountPage();closeConfirmation()">View order history</button></div></div>`)}
function closeConfirmation(){document.querySelector('#order-confirmation')?.remove();document.body.classList.remove('confirmation-open')}
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeConfirmation()});
const originalShowOrderConfirmation=showOrderConfirmation;showOrderConfirmation=function(...args){originalShowOrderConfirmation(...args);const overlay=document.querySelector('#order-confirmation');if(!overlay)return;document.body.classList.add('confirmation-open');overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.addEventListener('click',event=>{if(event.target===overlay)closeConfirmation()});requestAnimationFrame(()=>overlay.classList.add('is-visible'));overlay.querySelector('.checkout')?.focus()};
async function boot(){renderCategoryHub=(()=>{const original=renderCategoryHub;return function(){original();}})();renderLoading();
  // Render the shell immediately so Safari never stays blank while Supabase responds.
  if(!location.hash.startsWith("#account-")){if(location.hash.startsWith("#category-hub-")){localStorage.removeItem('pahalgam-browse-state');history.replaceState(null,'',location.pathname)}render()}
  try{
    const live=await Promise.race([loadProducts(),new Promise(resolve=>setTimeout(()=>resolve([]),7000))]);
    if(live.length){products=live.map(p=>({id:p.id,name:p.name,price:Number(p.price),mrp:p.mrp?Number(p.mrp):null,unit:p.unit||'',discount_percentage:p.discount_percentage?Number(p.discount_percentage):null,delivery_eta:p.delivery_eta||'',image_url:p.image_url||'',emoji:p.image_url?productImageMarkup({name:p.name,image_url:p.image_url,emoji:'🛍️'}):'🛍️',desc:p.description||'',detail_description:p.detail_description||p.product_description||'',health_benefits:p.health_benefits||'',shelf_life:p.shelf_life||'',disclaimer:p.disclaimer||'',customer_care_email:p.customer_care_email||'',return_policy:p.return_policy||'',seller:p.seller||'',seller_fssai:p.seller_fssai||'',category_name:p.category?.name||p.category_name,subcategory_name:p.subcategory?.name||p.subcategory_name,subcategory_id:p.subcategory_id,stock_quantity:p.stock_quantity}));cart=cart.filter(item=>products.some(product=>String(product.id)===String(item.id)));save();if(!location.hash.startsWith("#account-")){render()}}else console.warn('Supabase product request timed out or returned no active products; using fallback catalog.');
    currentUser=await Promise.race([getCurrentUser(),new Promise(resolve=>setTimeout(()=>resolve(null),4000))]);
    if(currentUser){await savePendingGuestAddress();startFloatingOrderStatus();if(location.hash.startsWith("#account-")){await accountPage();restoreAccountHash()}}
  }catch(error){console.warn('Live product load failed:',error.message);if(!location.hash.startsWith("#account-"))render()}
}
function productIsAvailable(product){return product?.stock_quantity==null||Number(product.stock_quantity)>0}
function decorateInventoryState(){document.querySelectorAll('.product').forEach(card=>{const name=card.querySelector('h3')?.textContent;const product=products.find(item=>item.name===name);if(!product||productIsAvailable(product))return;card.classList.add('out-of-stock');const button=card.querySelector('.add');if(button){button.disabled=true;button.textContent='Out of stock'}})}
const originalRender=render;render=function(){originalRender();document.querySelectorAll('.home-trust-strip,.trust-footer').forEach(node=>node.remove());addCategoryTrustDetails();addCustomerProductFilters();addProductUnits();addStickyCart();decorateInventoryState();const cartButton=document.querySelector('#cart');if(cartButton)cartButton.onclick=checkout};
