async function querySubcategoryProductsSafe(subcategory){const target=document.querySelector('#subcategory-products');if(!target)return;target.innerHTML='<div class="empty">Loading products…</div>';try{const work=(async()=>{const sub=await supabase.from('subcategories').select('*').eq('name',subcategory).maybeSingle();const id=sub?.data?.id;if(!id)throw new Error('Subcategory was not found in Supabase.');return await supabase.from('products').select('*').eq('subcategory_id',id).order('name')})();const result=await Promise.race([work,new Promise((_,reject)=>setTimeout(()=>reject(new Error('Supabase request timed out.')),10000))]);const rows=result?.data||[];renderRichProducts(rows,subcategory)}catch(error){target.innerHTML=`<div class="empty">Unable to load products: ${error.message}</div>`;console.warn('Subcategory query failed:',error)}}
