async function queryCategoryProducts(categoryName){const target=document.querySelector('#subcategory-products');if(!target)return;target.innerHTML='<div class="empty">Loading products…</div>';try{const category=await supabase.from('categories').select('id').eq('name',categoryName).maybeSingle();const id=category?.data?.id;if(!id)throw new Error('Category was not found in Supabase.');const sort=document.querySelector('#product-sort')?.value||'recent';const price=document.querySelector('#product-price')?.value||'all';const result=await supabase.from('products').select('*').eq('category_id',id).order(sort==='recent'?'created_at':'price',{ascending:sort==='price-low'});let rows=result?.data||[];if(price!=='all')rows=rows.filter(p=>{const value=Number(p.price||0);return price==='under-100'?value<100:price==='100-500'?value>=100&&value<=500:value>500});renderRichProducts(rows,categoryName)}catch(error){target.innerHTML=`<div class="empty">Unable to load products: ${error.message}</div>`;console.warn('Category query failed:',error)}}
queryCategoryProducts=async function(categoryName){const target=document.querySelector('#subcategory-products');if(!target)return;target.innerHTML='<div class="empty">Loading products…</div>';try{const category=await supabase.from('categories').select('id').eq('name',categoryName).maybeSingle();const categoryId=category?.data?.id;if(categoryId==null)throw new Error('Category was not found in Supabase.');const subcategories=await supabase.from('subcategories').select('id').eq('category_id',categoryId);const subcategoryIds=(subcategories?.data||[]).map(item=>item.id);const sort=document.querySelector('#product-sort')?.value||'recent';const price=document.querySelector('#product-price')?.value||'all';const result=subcategoryIds.length?await supabase.from('products').select('*').in('subcategory_id',subcategoryIds).order(sort==='recent'?'created_at':'price',{ascending:sort==='price-low'}):{data:[],error:null};let rows=result?.data||[];if(price!=='all')rows=rows.filter(p=>{const value=Number(p.price||0);return price==='under-100'?value<100:price==='100-500'?value>=100&&value<=500:value>500});renderRichProducts(rows,categoryName)}catch(error){target.innerHTML=`<div class="empty">Unable to load products: ${error.message}</div>`;console.warn('Category query failed:',error)}};
