queryCategoryProducts=async function(categoryName){const target=document.querySelector('#subcategory-products');if(!target)return;target.innerHTML='<div class="empty">Loading products…</div>';try{const category=await supabase.from('categories').select('id').eq('name',categoryName).maybeSingle();const categoryId=category?.data?.id;if(categoryId==null)throw new Error('Category was not found in Supabase.');const subcategories=await supabase.from('subcategories').select('id').eq('category_id',categoryId);const ids=(subcategories?.data||[]).map(item=>item.id);const sort=document.querySelector('#product-sort')?.value||'recent';const price=document.querySelector('#product-price')?.value||'all';const responses=await Promise.all(ids.map(id=>supabase.from('products').select('*').eq('subcategory_id',id).order(sort==='recent'?'created_at':'price',{ascending:sort==='price-low'})));let rows=responses.flatMap(result=>result?.data||[]);if(price!=='all')rows=rows.filter(p=>{const value=Number(p.price||0);return price==='under-100'?value<100:price==='100-500'?value>=100&&value<=500:value>500});renderRichProducts(rows,categoryName)}catch(error){target.innerHTML=`<div class="empty">Unable to load products: ${error.message}</div>`;console.warn('Category query failed:',error)}};
const originalAdd=add;add=async function(id){const product=products.find(item=>String(item.id)===String(id));if(!product){showToastMessage('This product is unavailable');return}const live=await supabase.from('products').select('stock_quantity,is_active').eq('id',id).maybeSingle();if(live?.data){product.stock_quantity=live.data.stock_quantity;product.is_active=live.data.is_active}const item=cart.find(line=>String(line.id)===String(id));if(!productIsAvailable(product)){showToastMessage('This product is out of stock');return}if(item&&product.stock_quantity!=null&&item.qty>=Number(product.stock_quantity)){showToastMessage(`Only ${product.stock_quantity} left in stock`);return}return originalAdd(id)};
changeProduct=function(id,amount){const product=products.find(item=>String(item.id)===String(id));if(!product)return;const item=cart.find(line=>String(line.id)===String(id));if(item)item.qty+=amount;else if(amount>0)cart.push({id:product.id,qty:1});cart=cart.filter(line=>line.qty>0);save();document.querySelectorAll('.product').forEach(card=>{if(card.querySelector('h3')?.textContent!==product.name)return;const footer=card.querySelector('.product-footer');if(!footer)return;const existing=cart.find(line=>String(line.id)===String(id));const control=footer.querySelector('.qty, .add');if(!control)return;control.outerHTML=existing?`<div class="qty"><button onclick="changeProduct('${id}',-1)">−</button><span>${existing.qty}</span><button onclick="changeProduct('${id}',1)">+</button></div>`:`<button class="add" data-product-id="${id}">Add +</button>`});const badge=document.querySelector('#cart .badge');if(badge)badge.textContent=cart.reduce((total,line)=>total+line.qty,0);if(document.querySelector('#checkout-overlay'))checkout(selectedDeliveryType);else bind()};
const originalRenderRichProducts=renderRichProducts;
