showCategoryPage=function(name){const hub=document.querySelector('#category-hub');if(!hub)return;hub.innerHTML=`<div class="category-page-head"><button class="text-button category-back" onclick="renderCategoryHub()">← All categories</button><div class="eyebrow">${categoryIcon(name)} Category</div><h2>${name}</h2><p>Browse related ${name.toLowerCase()} products.</p></div><div class="subcategory-grid"><button class="subcategory-tile active all-subcategory-tile" onclick="queryCategoryProducts('${name.replace(/'/g,"\\'")}')"><img class="all-subcategory-image" src="${categoryImage(name)}" alt="" loading="lazy"><strong>All</strong><span>View all products →</span></button>${categoryCatalog[name].map(sub=>`<button class="subcategory-tile" onclick="showSubcategoryProducts('${sub.replace(/'/g,"\\'")}')"><strong>${sub}</strong><span>View products →</span></button>`).join('')}</div><div class="product-filters"><label>Sort by <select id="product-sort"><option value="recent">Recently added</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option></select></label><label>Price <select id="product-price"><option value="all">Any price</option><option value="under-100">Under ₹100</option><option value="100-500">₹100–₹500</option><option value="over-500">Over ₹500</option></select></label></div><div id="subcategory-products"></div>`;document.querySelector('#product-sort').onchange=()=>queryCategoryProducts(name);document.querySelector('#product-price').onchange=()=>queryCategoryProducts(name);queryCategoryProducts(name)};
let customerOrderAlertTimer;function startCustomerOrderAlerts(){clearInterval(customerOrderAlertTimer);if(!currentUser)return;let baseline=new Map();customerOrderAlertTimer=setInterval(async()=>{try{const result=await supabase.from('orders').select('*').eq('user_id',currentUser.id).order('created_at',{ascending:false});const orders=result.data||[];if(!baseline.size){baseline=new Map(orders.map(order=>[String(order.id),order.status]));return}const changed=orders.find(order=>baseline.get(String(order.id))&&baseline.get(String(order.id)!==order.status));const fresh=orders.find(order=>!baseline.has(String(order.id)));if(fresh||changed){const order=fresh||changed;showToastMessage(fresh?`New order update: Order #${order.id}`:`Order #${order.id} is now ${String(order.status).replaceAll('_',' ')}`);if('Notification' in window&&Notification.permission==='granted')new Notification('Pahalgam Delivery',{body:fresh?`Your order #${order.id} has been received.`:`Your order #${order.id} is now ${order.status.replaceAll('_',' ')}.`});if(document.querySelector('.order-history'))await accountPage()}baseline=new Map(orders.map(order=>[String(order.id),order.status]))}catch(error){console.warn('Customer order alert refresh failed:',error.message)}},15000)}
const startCustomerOrderAlertsFixed=()=>{clearInterval(customerOrderAlertTimer);if(!currentUser)return;let baseline=new Map();let checking=false;const check=async()=>{if(checking)return;checking=true;try{const result=await supabase.from('orders').select('*').eq('user_id',currentUser.id).order('created_at',{ascending:false}),orders=result.data||[];if(!baseline.size){baseline=new Map(orders.map(order=>[String(order.id),order.status]));return}const changed=orders.find(order=>baseline.has(String(order.id))&&baseline.get(String(order.id))!==order.status),fresh=orders.find(order=>!baseline.has(String(order.id)));if(fresh||changed){const order=fresh||changed;showToastMessage(fresh?`New order update: Order #${order.id}`:`Order #${order.id} is now ${String(order.status).replaceAll('_',' ')}`);if('Notification' in window&&Notification.permission==='granted')new Notification('Pahalgam Delivery',{body:`Order #${order.id} is now ${String(order.status).replaceAll('_',' ')}.`});if(document.querySelector('.order-history'))await accountPage()}baseline=new Map(orders.map(order=>[String(order.id),order.status]))}catch(error){console.warn('Customer order alert refresh failed:',error.message)}finally{checking=false}};check();customerOrderAlertTimer=setInterval(check,3000)};const originalAccountPage=accountPage;accountPage=async function(){await originalAccountPage();startCustomerOrderAlertsFixed()};
const originalCustomerToast=showToastMessage;showToastMessage=message=>{const text=String(message);if(text.includes('is now')){const status=text.split(' is now ')[1];const labels={confirmed:'Your order is confirmed.',preparing:'Your order is being prepared.',out_for_delivery:'Your order is out for delivery.',delivered:'Your order has been delivered.',cancelled:'Your order has been cancelled.'};return originalCustomerToast(labels[status]||'Your order status has been updated.')}if(text.startsWith('New order update:'))return originalCustomerToast('Your order has been received.');return originalCustomerToast(text)};
