function applyVegetableAttributeFilters(){const type=document.querySelector('#produce-type-filter')?.value||'all',pack=document.querySelector('#produce-pack-filter')?.value||'all';const matches=(product,field,value)=>{if(value==='all')return true;const productContext=`${product.name||''} ${product.category_name||''} ${product.subcategory_name||''} ${product.desc||''}`.toLowerCase();const raw=String(product[field]||product.attributes?.[field]||product.metadata?.[field]||product.unit||product.description||'').toLowerCase(),text=raw.replace(/\s+/g,'');if(field==='produce_type'){if(value==='vegetables')return /vegetable|tomato|onion|potato|pea|corn|spinach|lettuce|cabbage|carrot|cucumber|capsicum|pepper|beans?|broccoli|cauliflower|brinjal|eggplant|okra|lady finger|radish|beetroot|garlic|ginger/i.test(productContext);if(value==='fruits')return /fruit|mango|apple|banana|pear|plum|orange|grape|papaya|guava|pomegranate|watermelon|melon|lemon|lime|kiwi|peach|apricot|cherry|strawberr/i.test(productContext);if(value==='herbs')return /herb|leafy|mint|coriander|cilantro|parsley|basil|spinach|lettuce|cabbage|fenugreek|methi|rocket/i.test(productContext)}return value==='2kg-plus'?/(2kg|[3-9]kg|[1-9][0-9]kg)/.test(text):text.includes(value.replace('-','').replace(/\s+/g,''))||raw.includes(value.replace('-',' '))};const rows=products.filter(product=>/fruit|vegetable|mango|apple|banana|pear|plum|orange|tomato|onion|potato|pea|corn|spinach|lettuce|cabbage|herb|mint|coriander/i.test(`${product.name} ${product.category_name||''} ${product.subcategory_name||''} ${product.desc||''}`)).filter(product=>matches(product,'produce_type',type)&&matches(product,'pack_weight',pack));renderRichProducts(rows,'Vegetables & Fruits')}
