function showSavedAddressState(){const saved=window.currentSavedCheckout;if(!saved?.delivery_address||!document.querySelector('#checkout-form')||document.querySelector('.saved-address-banner'))return;const form=document.querySelector('#checkout-form');const phone=saved.phone||currentUser?.phone||'';form.insertAdjacentHTML('beforebegin',`<div class="saved-address-banner"><strong>Delivering to: ${escapeHtml(saved.label||'Saved address')}</strong><span>${escapeHtml(saved.delivery_address)}</span>${phone?`<small>Phone: ${escapeHtml(phone)}</small>`:''}<button type="button" class="text-button" id="change-saved-address">Change address</button></div>`);form.style.display='none'}
async function showChangeAddressOptions(){if(!currentUser)return;document.querySelector('#address-choice-modal')?.remove();const result=await supabase.from('addresses').select('*').eq('user_id',currentUser.id).order('created_at',{ascending:false});const rows=result?.data||[];const options=rows.map(address=>{const value=[address.address_line||address.address].filter(Boolean).join(' · ');return `<button type="button" class="saved-address-choice" data-address-id="${escapeHtml(address.id)}"><strong>${escapeHtml(address.label||'Saved address')}</strong><span>${escapeHtml(value||'Address details unavailable')}</span></button>`}).join('');document.body.insertAdjacentHTML('beforeend',`<div class="auth-modal" id="address-choice-modal"><div class="auth-card"><button class="close" onclick="this.closest('#address-choice-modal').remove()">×</button><div class="eyebrow">Delivery address</div><h2>Choose an address</h2><div class="saved-address-choice-list">${options||'<p class="muted">No saved addresses yet.</p>'}</div><button type="button" class="checkout">＋ Add a new address</button></div></div>`)}
function showCheckoutFields(){window.editingSavedAddress=true;const form=document.querySelector('#checkout-form');document.querySelector('.saved-address-banner')?.remove();if(form){form.hidden=false;form.style.display='grid';form.querySelectorAll('.field').forEach(field=>field.hidden=false)}}
function revealSavedCheckoutPayment(){const form=document.querySelector('#checkout-form');if(!form||window.editingSavedAddress)return;form.style.display='grid';form.querySelectorAll('.field').forEach(field=>{if(field.querySelector('[data-field]'))field.hidden=true})}
window.showCheckoutFields=showCheckoutFields;
document.addEventListener('click',event=>{if(event.target.closest('#change-saved-address')){event.preventDefault();showChangeAddressOptions()}});
document.addEventListener('click',event=>{if(event.target.closest('.saved-address-choice'))setTimeout(()=>{const saved=window.currentSavedCheckout;if(saved?.delivery_address)localStorage.setItem('pahalgam-selected-address',JSON.stringify({label:saved.label||'Saved address',address:saved.delivery_address,phone:saved.phone||''}))},0)});
document.addEventListener('click',async event=>{const choice=event.target.closest('.saved-address-choice');const addButton=event.target.closest('#address-choice-modal .checkout');if(!choice&&!addButton)return;event.preventDefault();event.stopImmediatePropagation();if(addButton){document.querySelector('#address-choice-modal')?.remove();showCheckoutFields();addNewAddress(event);return}if(!currentUser)return;const result=await supabase.from('addresses').select('*').eq('id',choice.dataset.addressId).eq('user_id',currentUser.id).maybeSingle();const address=result?.data;if(!address)return;const phone=currentUser.phone||'';const selected={label:compactDeliveryLabel(`${address.label||'Saved address'} · ${String(address.address_line||address.address||'').split(',')[0].trim()}`),address:address.address_line||address.address||'',phone};window.currentSavedCheckout={...(window.currentSavedCheckout||{}),label:selected.label,delivery_address:selected.address,phone};localStorage.setItem('pahalgam-selected-address',JSON.stringify(selected));localStorage.setItem('pahalgam-last-delivery',JSON.stringify({address:selected.address,label:`${selected.label} · ${selected.address}`}));document.querySelector('#address-choice-modal')?.remove();document.querySelector('.saved-address-banner')?.remove();window.editingSavedAddress=false;showSavedAddressState()},true);
const savedAddressObserver=new MutationObserver(()=>{if(!window.editingSavedAddress){showSavedAddressState();revealSavedCheckoutPayment()}});savedAddressObserver.observe(document.body,{childList:true,subtree:true});
let savedCheckoutHydrated=false;const savedCheckoutHydrator=new MutationObserver(async()=>{if(savedCheckoutHydrated||!currentUser||!document.querySelector('#checkout-form'))return;savedCheckoutHydrated=true;const [addressResult,profileResult]=await Promise.all([supabase.from('addresses').select('*').eq('user_id',currentUser.id).order('created_at',{ascending:false}).maybeSingle(),loadCurrentProfile()]);const address=addressResult?.data||{};const profile=profileResult?.data||{};window.currentSavedCheckout={...(window.currentSavedCheckout||{}),customer_name:window.currentSavedCheckout?.customer_name||profile.full_name||currentUser.user_metadata?.full_name||'',phone:window.currentSavedCheckout?.phone||profile.phone||currentUser.phone||'',delivery_address:window.currentSavedCheckout?.delivery_address||address.address_line||address.address||'',label:address.label||'Saved address',hotel_name:address.hotel_name,room_number:address.room_number,delivery_instructions:address.delivery_instructions};document.querySelectorAll('#checkout-form [data-field]').forEach(input=>{const value=window.currentSavedCheckout[fieldKey(selectedDeliveryType,input.dataset.field)]||'';if(value)input.value=value});if(address.address_line)showSavedAddressState()});savedCheckoutHydrator.observe(document.body,{childList:true,subtree:true});
async function hydrateDeliveryTargetWithFullAddress(){const target=document.querySelector('#delivery-target');if(!target||!currentUser)return;try{const [addressResult,profileResult]=await Promise.all([supabase.from('addresses').select('*').eq('user_id',currentUser.id).order('created_at',{ascending:false}).maybeSingle(),loadCurrentProfile()]);const address=addressResult?.data;if(!address)return;const phone=profileResult?.data?.phone||currentUser.phone||'';const value=normalizeDeliveryLabel([address.address_line,address.hotel_name,address.room_number?`Room ${address.room_number}`:'',phone?`Phone ${phone}`:'',address.delivery_instructions].filter(Boolean).join(' · ')||'Pahalgam');const street=String(address.address_line||address.address||'').split(',')[0].trim();const label=normalizeDeliveryLabel(`${address.label||'Home'} · ${street}`);localStorage.setItem('pahalgam-last-delivery',JSON.stringify({address:value,label}));const name=target.querySelector('strong');if(name){name.textContent=label;name.title=label}const savedButton=target.querySelector('.delivery-saved-option');const savedText=savedButton?.querySelector('span:last-child');if(savedText)savedText.textContent=label}catch(error){console.warn('Delivery target unavailable:',error.message)}}
