async function addCustomerOrderAddresses(){const section=document.querySelector('.order-history');if(!section||section.dataset.addressesLoaded||!currentUser)return;section.dataset.addressesLoaded='1';const result=await supabase.from('orders').select('id,delivery_address,hotel_name,room_number,business_name').eq('user_id',currentUser.id).order('created_at',{ascending:false});const byId=new Map((result.data||[]).map(order=>[String(order.id),order]));section.querySelectorAll('.cart-row').forEach(row=>{const id=row.querySelector('.cart-info strong')?.textContent?.replace(/^Order #/,'').trim(),order=byId.get(String(id));if(!order)return;const address=[order.delivery_address,order.hotel_name,order.business_name,order.room_number?`Room ${order.room_number}`:''].filter(Boolean).join(' · ')||'Address not provided';const info=row.querySelector('.cart-info');if(info&&!info.querySelector('.order-address'))info.insertAdjacentHTML('beforeend',`<small class="order-address">Delivery address: ${escapeHtml(address)}</small>`)})}
function renderAuthForm(mode='signin'){const card=document.querySelector('#auth-modal .auth-card');if(!card)return;card.innerHTML=`<button class="close" onclick="closeAuthModal()">×</button><div class="eyebrow">Welcome to GroVale</div><h2>${mode==='signup'?'Create account':'Sign in'}</h2><p>${mode==='signup'?'Create your GroVale account with email and password.':'Use your email address and password to continue.'}</p><input id="auth-email" type="email" autocomplete="email" required placeholder="you@example.com"/><input id="auth-password" type="password" autocomplete="new-password" required minlength="6" placeholder="Password (at least 6 characters)"/>${mode==='signup'?'<input id="auth-password-confirm" type="password" autocomplete="new-password" required minlength="6" placeholder="Confirm password"/>':''}<button class="checkout" onclick="${mode==='signup'?'createAccount()':'signInWithPassword()'}">${mode==='signup'?'Create account':'Sign in'}</button>${mode==='signin'?'<button class="text-button" onclick="sendPasswordResetRequest()">Forgot password?</button><button class="text-button" onclick="renderAuthForm(\'signup\')">Create account</button>':'<button class="text-button" onclick="renderAuthForm(\'signin\')">Already have an account? Sign in</button>'}<button class="text-button" onclick="closeAuthModal()">Continue browsing</button><div id="auth-message"></div>`}
showAuthModal=function(){if(document.querySelector('#auth-modal'))return;document.body.insertAdjacentHTML('beforeend','<div class="auth-modal" id="auth-modal"><div class="auth-card"></div></div>');renderAuthForm('signin')};
let createAccount=async function(){const email=document.querySelector('#auth-email')?.value.trim(),password=document.querySelector('#auth-password')?.value,confirm=document.querySelector('#auth-password-confirm')?.value,message=document.querySelector('#auth-message'),button=document.querySelector('#auth-modal .checkout');if(!email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){message.textContent='Enter a valid email address.';return}if(!password||password.length<6){message.textContent='Password must be at least 6 characters.';return}if(password!==confirm){message.textContent='Passwords do not match.';return}button.disabled=true;button.textContent='Creating account…';const result=await signUpWithEmail(email,password);if(result.error){message.textContent=result.error.message||'Unable to create account.';button.disabled=false;button.textContent='Create account';return}message.textContent='Account created. Check your email to verify your account, then sign in.';button.disabled=false;button.textContent='Create account'};
let sendPasswordResetRequest=async function(){const email=document.querySelector('#auth-email')?.value.trim(),message=document.querySelector('#auth-message');if(!email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){message.textContent='Enter your email address first.';return}const result=await sendPasswordReset(email,`${location.origin}${location.pathname}`);message.textContent=result.error?'Unable to send the reset email. Please try again.':'If that email is registered, a password reset link has been sent.'};
window.showAuthModal=showAuthModal;window.createAccount=createAccount;window.renderAuthForm=renderAuthForm;window.sendPasswordResetRequest=sendPasswordResetRequest;
