function subcategorySidebarIcon(name){const value=String(name||'').toLowerCase();if(/atta|flour/.test(value))return'🌾';if(/rice/.test(value))return'🍚';if(/dal|pulse/.test(value))return'🫘';if(/vegetable/.test(value))return'🥬';if(/fruit|apple|mango|banana/.test(value))return'🍎';if(/frozen/.test(value))return'🧊';if(/leaf|green/.test(value))return'🥗';if(/herb|mint|coriander/.test(value))return'🌿';if(/oil/.test(value))return'🫗';if(/ghee/.test(value))return'🧈';if(/spice|masala/.test(value))return'🌶️';if(/milk|dairy/.test(value))return'🥛';if(/bread/.test(value))return'🍞';if(/egg/.test(value))return'🥚';if(/chicken|meat/.test(value))return'🍗';if(/fish/.test(value))return'🐟';if(/clean|detergent|laundry/.test(value))return'🧼';if(/tea|coffee/.test(value))return'☕';if(/drink|juice|water/.test(value))return'🧃';if(/sweet|chocolate|cake/.test(value))return'🍫';if(/ice cream|kulfi|frozen dessert/.test(value))return'🍨';if(/chip|namkeen|popcorn/.test(value))return'🍿';if(/soap|body|bath/.test(value))return'🧴';if(/shampoo|hair/.test(value))return'🪮';if(/skin|face|beauty/.test(value))return'🧖';if(/baby|diaper/.test(value))return'👶';if(/tooth|oral/.test(value))return'🪥';if(/shav|beard|groom/.test(value))return'🪒';if(/phone|mobile|charger|headphone/.test(value))return'🔌';if(/game|stationery|notebook/.test(value))return'🎲';if(/travel|luggage|bag/.test(value))return'🧳';return'🛍️'}
function subcategorySidebarImage(name){const value=String(name||'').toLowerCase();const dedicated={'fresh vegetables':'public/sidebar-fresh-vegetables.jpg','fresh fruits':'public/sidebar-fresh-fruits.jpg','frozen vegs':'public/sidebar-local-fruits.jpg','local fruits':'public/sidebar-herbs.jpg','seasonal':'public/sidebar-leafy-greens.jpg','leafy greens':'public/sidebar-frozen-vegetables.jpg','herbs':'public/sidebar-fresh-vegetables.jpg','atta & flour':'public/sidebar-atta-flour.jpg','rice':'public/sidebar-rice.jpg','dal & pulses':'public/sidebar-dal-pulses.jpg','cooking oil':'public/sidebar-cooking-oil.jpg','ghee':'public/sidebar-ghee.jpg','spices & masala':'public/sidebar-spices-masala.jpg','milk & dairy':'public/sidebar-milk-dairy.jpg','bread':'public/sidebar-bread.jpg','eggs':'public/sidebar-eggs.jpg','bakery & biscuits':'public/sidebar-bakery-biscuits.jpg','cakes & pastries':'public/sidebar-cakes-pastries.jpg','biscuits':'public/sidebar-biscuits.jpg','snacks':'public/sidebar-snacks.jpg','chicken':'public/sidebar-chicken.jpg','meat':'public/sidebar-meat.jpg','fish':'public/sidebar-fish.jpg','cookware':'public/sidebar-cookware.jpg','kitchen tools':'public/sidebar-kitchen-tools.jpg','small appliances':'public/sidebar-small-appliances.jpg','frozen snacks':'public/sidebar-frozen-snacks.jpg','frozen vegetables':'public/sidebar-frozen-vegetables.jpg','frozen meals':'public/sidebar-frozen-meals.jpg'};return dedicated[value]||''}
