function applyVegetableSidebar(){const hub=document.querySelector('#category-hub'),grid=hub?.querySelector('.subcategory-grid'),productsArea=hub?.querySelector('#subcategory-products'),heading=hub?.querySelector('.category-page-head h2');if(!hub||!grid||!productsArea||!heading||hub.querySelector('.category-page-layout'))return;const categoryName=heading.textContent.trim();const layout=document.createElement('div');layout.className='category-page-layout';const sidebar=document.createElement('aside');sidebar.className='subcategory-filter-sidebar';sidebar.setAttribute('aria-label',`${categoryName} filters`);sidebar.innerHTML=`<div class="eyebrow">Filter by</div><strong>${escapeHtml(categoryName)}</strong>`;grid.querySelectorAll('.subcategory-tile').forEach(tile=>sidebar.append(tile));applySidebarIcons(sidebar);const results=document.createElement('main');results.className='category-page-results';const filterBar=hub.querySelector('.product-filters');if(filterBar)results.append(filterBar);results.append(productsArea);layout.append(sidebar,results);grid.replaceWith(layout);requestAnimationFrame(fitSidebarToViewport)}
