function fitSidebarToViewport(){const sidebar=document.querySelector('.subcategory-filter-sidebar');const results=document.querySelector('.category-page-results');if(!sidebar)return;const top=sidebar.getBoundingClientRect().top;const available=Math.max(220,window.innerHeight-top-16);sidebar.style.height=`${available}px`;sidebar.style.maxHeight=`${available}px`;sidebar.style.overflowY='auto';if(results){const mobile=window.matchMedia('(max-width: 700px)').matches;results.style.height=mobile?'auto':`${available}px`;results.style.maxHeight=mobile?'none':`${available}px`;results.style.overflowY=mobile?'visible':'auto';results.style.overscrollBehavior=mobile?'auto':'contain';results.style.paddingBottom=mobile?'140px':'80px';results.style.boxSizing='border-box'}}
