setInterval(()=>{const hash=location.hash;const name=hash.startsWith('#category-hub-')?decodeURIComponent(hash.slice('#category-hub-'.length)):'';const hub=document.querySelector('#category-hub');if(name&&hub&&!hub.querySelector('.category-page-head')&&hub.querySelector('.section-head h2')?.textContent==='Categories')showCategoryPage(name)},500);
