const originalCategoryProductQuery=queryCategoryProducts;
 queryCategoryProducts=async function(name){
  if(name!=='Vegetables & Fruits')return originalCategoryProductQuery(name);
  const target=document.querySelector('#subcategory-products');
  if(!target)return;
  target.innerHTML='<div class="empty">Loading products…</div>';
  try{
   const category=await supabase.from('categories').select('id').eq('name',name).maybeSingle();
   const categoryId=category?.data?.id;
   if(categoryId==null)throw new Error('Category was not found in Supabase.');
   const subcategories=await supabase.from('subcategories').select('id').eq('category_id',categoryId);
   const ids=(subcategories?.data||[]).map(item=>item.id);
   const responses=await Promise.all(ids.map(id=>supabase.from('products').select('*').eq('subcategory_id',id).order('created_at',{ascending:false})));
   const rows=responses.flatMap(result=>result?.data||[]);
   renderRichProducts(rows,name);
  }catch(error){
   target.innerHTML=`<div class="empty">Unable to load products: ${escapeHtml(error.message||String(error))}</div>`;
   console.warn('Category query failed:',error);
  }
 };
window.queryCategoryProducts=queryCategoryProducts;
const originalSimpleCategoryHub=renderCategoryHub;
renderCategoryHub=function(){originalSimpleCategoryHub();const hub=document.querySelector('#category-hub');if(!hub)return;hub.querySelector('.eyebrow')?.remove();if(!hub.querySelector('.view-all-categories'))hub.querySelector('.section-head')?.insertAdjacentHTML('beforeend','<button type="button" class="view-all-categories">View all categories</button>');hub.classList.add('category-preview-collapsed');const toggle=hub.querySelector('.view-all-categories');if(toggle&&!toggle.dataset.bound){toggle.dataset.bound='true';toggle.onclick=()=>{const expanded=hub.classList.toggle('category-preview-expanded');hub.classList.toggle('category-preview-collapsed',!expanded);toggle.textContent=expanded?'Show fewer categories':'View all categories'}}};
