function applyHomepageSimplification(){const hub=document.querySelector('#category-hub');if(!hub||hub.querySelector('.category-page-head')||hub.dataset.simplified)return;hub.dataset.simplified='true';hub.querySelector('.eyebrow')?.remove();hub.classList.remove('category-preview-collapsed');hub.classList.add('category-preview-expanded');hub.querySelector('.view-all-categories')?.remove()}
