function applyGroceryQuickNav(){const header=document.querySelector('.header'),inner=header?.querySelector('.header-inner');if(!header||!inner||header.querySelector('.grocery-quick-nav'))return;const groups=[['all','🛍️','All'],['Grocery & Kitchen','🥦','Grocery'],['Electronics & Travelling','📱','Electronics'],['Beauty & Personal Care','🧴','Beauty'],['Health & Pharma','💊','Pharmacy'],['Household Essentials','🎁','Gifting'],['Snacks & Drinks','🍿','Snacks']];inner.insertAdjacentHTML('afterend',`<div class="grocery-quick-nav universal-quick-nav site-quick-nav" aria-label="Browse store sections">${groups.map(([key,icon,label])=>`<button type="button" aria-label="${label}" class="${key==='all'?'is-selected':''}" data-quick-group="${key}"><span>${icon}</span><strong>${label}</strong></button>`).join('')}</div>`);const sectionTargets={Electronics:'Electronics & Travelling',Beauty:'Beauty & Personal Care',Pharmacy:'Beauty & Personal Care',Gifting:'Household Essentials',Snacks:'Snacks & Drinks'};header.querySelectorAll('[data-quick-group]').forEach(button=>button.onclick=()=>{header.querySelectorAll('[data-quick-group]').forEach(item=>item.classList.remove('is-selected'));button.classList.add('is-selected');const key=button.dataset.quickGroup;if(key==='all'||key==='Grocery & Kitchen'){localStorage.removeItem('pahalgam-browse-state');history.replaceState(null,'',location.pathname);renderCategoryHub();const hub=document.querySelector('#category-hub');hub?.classList.add('category-preview-expanded');hub?.classList.remove('category-preview-collapsed');window.scrollTo({top:0,behavior:'smooth'});return}renderCategoryHub();const hub=document.querySelector('#category-hub');hub?.classList.add('category-preview-expanded');hub?.classList.remove('category-preview-collapsed');const label=button.querySelector('strong')?.textContent?.trim();const targetKey=sectionTargets[label]||key;const target=[...document.querySelectorAll('.category-group h3')].find(title=>title.textContent.trim()===targetKey)?.closest('.category-group');if(target){const headerHeight=header.getBoundingClientRect().height;const top=Math.max(0,target.getBoundingClientRect().top+window.scrollY-headerHeight-8);window.scrollTo({top,behavior:'smooth'})}})}
setInterval(applyGroceryQuickNav,250);
const showCategoryPageWithScrollReset=showCategoryPage;
showCategoryPage=function(name){showCategoryPageWithScrollReset(name);requestAnimationFrame(()=>{const head=document.querySelector('#category-hub .category-page-head');if(head){const header=document.querySelector('.header')?.getBoundingClientRect().height||0;window.scrollTo({top:Math.max(0,window.scrollY+head.getBoundingClientRect().top-header-8),behavior:'auto'})}})};
