let deferredInstallPrompt=null;
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstallPrompt=event;document.documentElement.classList.add('pwa-installable')});
window.installGroValeApp=async()=>{if(deferredInstallPrompt){deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;document.documentElement.classList.remove('pwa-installable');return}showToastMessage(/iphone|ipad|macintosh/i.test(navigator.userAgent)?'On iPhone: tap Share, then Add to Home Screen.':'Use your browser menu and choose Install app or Add to Home screen.')};
